style.css:
@-moz-document domain("weather.com") {
/*
   * weather.com (The Weather Channel / IBM) is a hashed CSS-module React SPA:
   * the styled class names (styles--cards--Yo-aJ, ...) ROTATE on every deploy,
   * which is exactly what rotted the previous comprehensive theme. So this theme
   * is built ENTIRELY on STABLE hooks: the design-system CSS custom properties
   * (--background / --card / --popover / --border / ... shadcn-style tokens),
   * the Tailwind utility classes the app ships (bg-white, bg-gray-100, bg-card,
   * text-gray-900, border-gray-200, ...) and the rich data-testid attributes
   * (header-main, sidebar-navigation, header-search, current-conditions,
   * daily-forecast, SemiCircleGauge, DonutChart, ...). None of these are hashed.
   *
   * HANDS OFF the weather data itself: radar/satellite maps (DynamicMap, the
   * Mapbox tiles), condition icons, the temperature color scale, AQI / UV /
   * pollen / allergy color codes and severe-weather alert banners are left
   * intact -- we only retheme the surrounding chrome, surfaces, text, borders
   * and the white chrome of the SVG charts/gauges, never the colored data.
   */

  :root {
    color-scheme: dark;

    --wx-base: #14181d;          /* page base                     */
    --wx-surface: #1c2128;       /* cards / modules               */
    --wx-surface-2: #161d27;     /* alt elevated / wells / zebra  */
    --wx-chrome: #0d1117;        /* header / footer / sidebar     */
    --wx-border: #262c33;        /* subtle border                 */
    --wx-border-2: #2d333b;      /* component border              */
    --wx-text: #e6edf3;          /* primary text                  */
    --wx-text-2: #c4cdd6;        /* body text                     */
    --wx-text-muted: #8b949e;    /* metadata / muted              */
    --wx-link: #5fb0e6;          /* refined weather.com blue      */
    --wx-link-hover: #9bd4ff;

    /* ---- design-system tokens (shadcn / Tailwind v4) -------------------- */
    /* Remapping these themes most cards, popovers, inputs and text at once,
       durably, because the app references them as bg-card / bg-background /
       text-foreground / border-border etc. rather than hardcoded colors. */
    --background: #14181d !important;
    --foreground: #e6edf3 !important;
    --card: #1c2128 !important;
    --card-foreground: #e6edf3 !important;
    --popover: #1c2128 !important;
    --popover-foreground: #e6edf3 !important;
    --primary: #5fb0e6 !important;
    --primary-foreground: #0d1117 !important;
    --secondary: #1c2128 !important;
    --secondary-foreground: #e6edf3 !important;
    --muted: #161d27 !important;
    --muted-foreground: #8b949e !important;
    --accent: #1c2128 !important;
    --accent-foreground: #e6edf3 !important;
    --border: #262c33 !important;
    --input: #2d333b !important;
    --ring: #5fb0e6 !important;
    --text-secondary: #8b949e !important;
  }

  /* ---- base ------------------------------------------------------------- */
  html,
  body,
  #app,
  #appWrapper,
  main,
  [data-testid="page-wrapper"] {
    background-color: var(--wx-base) !important;
    color: var(--wx-text-2) !important;
  }

  /* Soften every light border to a subtle dark one (specific ones re-handled
     below). Maps / charts are excluded at the bottom. */
  * {
    border-color: var(--wx-border) !important;
  }
  /* ...but weather.com uses Tailwind's EXPLICIT border utilities as semantic
     indicators, and the blanket rule above swallowed all three:
     - `border-black` marks the SELECTED unit in the °F / °C / Hybrid picker
       (the others carry `border-transparent`), so the selected unit lost its
       underline while the unselected ones GAINED a phantom 2px line -- the
       control no longer showed which unit was active.
     - `border-white` is the ring of the map's location pin.
     Restore each to its intent (black -> light, since the surface flipped). */
  .border-transparent {
    border-color: transparent !important;
  }
  .border-black,
  .border-white {
    border-color: var(--wx-text) !important;
  }
  /* ...but the article byline avatar is `border-2 border-white` on the white article
     body, i.e. an INVISIBLE spacer ring, so lifting it to --wx-text drew a bright halo
     round the author photo that weather.com never shows. Keep the ring, drop the paint. */
  img[class*="authorImage"] {
    border-color: transparent !important;
  }
  /* Tailwind's hover border variants are a real affordance the blanket rule pins flat:
     the Today's-Details tiles darken border-gray-200 -> -400 on hover and the carousel
     arrows go border-black, and both froze at --wx-border with no cue at all. On dark the
     equivalent move is to brighten; the muted ink is the visible-but-quiet step. */
  [class*="hover:border-gray-300"]:hover,
  [class*="hover:border-gray-400"]:hover,
  [class*="hover:border-gray-500"]:hover,
  [class*="hover:border-black"]:hover {
    border-color: var(--wx-text-muted) !important;
  }
  /* the news-hub byline block ("By <author>") is set off by a 1px brand-blue left rule
     (`border-l border-[#679CED]`) -- a chromatic accent the blanket reset above erases.
     #679ced reads on the dark card, so it keeps its own value. Both hex spellings
     because the attribute match is case-sensitive. */
  [class*="border-[#679CED]"],
  [class*="border-[#679ced]"] {
    border-color: #679ced !important;
  }

  /* ---- header / sidebar chrome ----------------------------------------- */
  [data-testid="header-main"],
  [data-component="header-main"],
  header,
  [data-testid="subnavigation"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text) !important;
  }

  /* the legacy header (radar / monthly) ships a `Skip to Main Content` skip-nav
     link (MainMenuHeader--accessibilityLink) that is off-screen until keyboard
     focus, then reveals a WHITE pill. Our global `a { color: var(--wx-link) }`
     paints its text a light blue on that white pill -> ~2.3:1 light-on-light on
     Tab-focus. Darken the pill to the chrome so the blue link text reads. */
  [class*="MainMenuHeader--accessibilityLink"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-link) !important;
  }

  /* The Weather Channel wordmark is a KNOCKOUT logo: one evenodd <path> paints the
     #003399 square and the letters are HOLES punched through it, so the glyphs are
     whatever sits BEHIND the svg. On the site's white page they read white; on our
     dark chrome they filled with near-black and the wordmark went unreadable
     (blue-on-black letters). Nothing about it is a background-color or a fill, so
     every scan passed. Put the white backdrop back BEHIND the mark (exactly what the
     native page provides) -- the letters read white again and the blue square, which
     is the actual painted geometry, is untouched. Three carriers, one per frontend and
     no shared hook: the SPA header / rail has the Tailwind arbitrary class, the legacy
     Daybreak rail its module class, and support.weather.com's "Browse by Brand" tile is
     a bare inline <svg> whose only distinguishing attribute is its 48x48 viewBox -- the
     Weather Underground tile beside it is 50x50 and must NOT take a white plate. */
  svg[class*="text-[#003399]"],
  svg[class*="SidebarNavigation--logoIcon"],
  .brands svg[viewBox="0 0 48 48"] {
    background-color: #ffffff !important;
  }

  /* left sidebar navigation rail */
  [data-testid="sidebar-navigation"],
  [data-component="sidebar-navigation"],
  nav[data-testid="sidebar-navigation"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text-2) !important;
  }
  /* sidebar links + their hover/active fills (ship bg-gray-100 / f2f2f2) */
  [data-testid="sidebar-navigation"] a,
  [data-testid="sidebar-navigation"] button {
    background-color: transparent !important;
    color: var(--wx-text-2) !important;
  }
  [data-testid="sidebar-navigation"] a:hover,
  [data-testid="sidebar-navigation"] button:hover {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  /* weather.com marks the CURRENT page in the rail with brand blue (#3a61cc) on the
     label AND on the icon (the icon is `text-inherit`), on a grey pill. Our rules
     above repainted that blue plain light, so the active rail item read exactly like
     every inactive one and only the pill fill distinguished it. Restore the accent
     with the theme's link blue (weather.com's own #3a61cc only reaches 2.9:1 on the
     dark pill); the pill keeps its elevated dark fill. */
  [data-testid="sidebar-navigation"] a[aria-current],
  [data-testid="sidebar-navigation"] [aria-current="page"],
  [data-testid="sidebar-navigation"] a.bg-gray-100 {
    background-color: var(--wx-surface) !important;
    color: var(--wx-link) !important;
  }
  /* the rail item's LABEL is a <p>, which the generic `p` text rule further down
     repaints body-grey -- without this the icon turned blue and the word beside it
     stayed grey. Colour the label with its item (no fill: the pill already has one). */
  [data-testid="sidebar-navigation"] a[aria-current] p,
  [data-testid="sidebar-navigation"] [aria-current="page"] p,
  [data-testid="sidebar-navigation"] a.bg-gray-100 p {
    color: var(--wx-link) !important;
  }
  /* the LEGACY rail (monthly / maps / the /forecast/* Daybreak routes) carries the same
     `data-testid="sidebar-navigation"`, but marks the current page with a
     `SidebarNavigation--active` class and a #f2f2f2 pill -- no aria-current, no
     bg-gray-100 -- so the blanket `a { background: transparent }` above blanked the one
     thing that distinguished it and every rail item rendered identically. The pill is
     the site's ONLY marker here (its ink is the same near-black as the inactive items),
     so restore the fill alone; adding an accent would have to be repeated on the icon,
     which the Icon--icon rules match directly. */
  [data-testid="sidebar-navigation"] a[class*="SidebarNavigation--active"] {
    background-color: var(--wx-surface) !important;
  }
  /* the location-pill popover anchor (rounded-4xl bg-white wrapper) */
  [data-slot="popover-anchor"],
  .rounded-4xl.bg-white {
    background-color: var(--wx-surface) !important;
  }

  /* the radar / interactive-map pages use a LEGACY collapsed sidebar (a
     different component from the data-testid rail above): the nav itself is
     ~636px tall but its WRAPPER stretches the full viewport height and ships a
     white background, so a bright strip shows BELOW the nav items. The region
     wrapper classes (.region-sidebarNavigation / .regionSidebarNavigation) are
     stable layout hooks; the SidebarNavigation--* module names are stable
     prefixes (only the trailing build-hash rotates). Darken them to the
     chrome so the whole rail reads dark top-to-bottom. */
  .region-sidebarNavigation,
  .regionSidebarNavigation,
  [class*="SidebarNavigation--sidebarWrapper"],
  [class*="SidebarNavigation--sidebar"] {
    background-color: var(--wx-chrome) !important;
  }
  /* CRITICAL: the legacy layout ALSO ships a `SidebarNavigation--isOverlay`
     variant of that wrapper -- a position:fixed, z-index:1000, FULL-VIEWPORT,
     pointer-events:none layer that is normally TRANSPARENT (the closed
     mobile-overlay backdrop). The broad rule above matched it and painted it
     opaque chrome, so it covered the ENTIRE page with a dark sheet and blanked
     every legacy-layout page (monthly, etc.). It is pointer-events:none, so the
     page stayed clickable but rendered all-dark. Force the overlay variant back
     to transparent; the real (docked) sidebar wrapper keeps its dark fill. */
  [class*="SidebarNavigation--isOverlay"] {
    background-color: transparent !important;
  }

  /* ---- legacy "Daybreak" layout surfaces (Monthly, and other not-yet-migrated
     routes) ------------------------------------------------------------------
     Some routes (notably the Monthly calendar) still ship the OLD Daybreak/Helios
     React layout instead of the new data-testid/Tailwind SPA. Its cards are
     `section.card.Card--card--<hash>` (white), the page header is `#regionHeader`
     (white), day-grid dividers are `Calendar--line--<hash>` (#dedede) and the
     day-part wells are `DaypartDetails--DetailsTable--<hash>` (#e8e8e8). The new
     layout's tokens/utilities don't touch these, so the calendar card rendered
     white with our lifted light text on top (light-on-light). Darken the legacy
     module surfaces via their STABLE prefixes (only the trailing hash rotates);
     the colored condition icons + the temperature numbers keep their own hues. */
  [class*="Card--card"],
  /* the `CalendarMonthPicker--` prefix also lands on the nav's "View" button (a
     `Button--primary`): its fill + ink pair IS the enabled/disabled cue, so it is
     exempt and keeps the site's own primary/disabled colours. */
  [class*="CalendarMonthPicker--"]:not([class*="viewButton"]),
  [class*="DailyForecast--"],
  /* id-prefixed forms out-rank module CSS-in-JS rules injected after our sheet
     (which otherwise win same-specificity ties -- seen on the radar map card,
     the radar right rail and the footer). */
  [id^="Wxu"] [class*="Card--card"],
  aside[class*="region-sidebar"],
  aside[class*="regionSidebar"],
  [class*="Layers--overlayGroup"],
  /* the 404 / not-found fallback (e.g. an alerts URL with no active alerts)
     renders white promo teaser cards via WxuNotFound -> NotFound--pageLink. */
  [class*="NotFound--pageLink"],
  [class*="NotFound--notFound"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  #regionHeader,
  [class*="region-header"],
  [class*="regionHeader"] {
    background-color: var(--wx-chrome) !important;
  }
  [class*="DaypartDetails--DetailsTable"],
  [class*="DetailsTable--"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="Calendar--line"] {
    background-color: var(--wx-border) !important;
  }
  /* the calendar day cells + day-part list rows draw a light #dedede grid border
     (set by a module rule with !important, so the global `* { border-color }`
     loses); darken the grid so it reads as a subtle dark lattice on the card.
     Card-scoped to out-rank any later-injected module rule. */
  [class*="Card--card"] [class*="CalendarDateCell"],
  [class*="Card--card"] [class*="DetailsTable--listItem"],
  [class*="CalendarDateCell--dayCell"] {
    border-color: var(--wx-border) !important;
  }
  /* the day-cell's WEEK-DIVIDER (border-top) is set by a SEPARATE higher-specificity
     Helios rule (a [dir]-prefixed .Calendar--gridWrapper .CalendarDateCell--dayCell
     selector) targeting border-top-color: #dedede !important -- so it out-specifies
     the rule above and only the TOP edge stayed light (the bottom/right edges took
     our dark border). It rendered as a bright horizontal lattice line between weeks.
     Re-match it with the gridWrapper ancestor + button tag to raise our specificity
     above the module rule, and pin border-top-color explicitly. */
  [class*="Card--card"] [class*="Calendar--gridWrapper"] button[class*="CalendarDateCell--dayCell"],
  [class*="Calendar--gridWrapper"] button[class*="CalendarDateCell--dayCell"] {
    border-color: var(--wx-border) !important;
    border-top-color: var(--wx-border) !important;
  }
  /* the legacy location search ships a light #f2f2f2 fill via a high-specificity
     module rule that beats the generic `input` override -- pin it by id + module
     prefix so the field reads dark. */
  #headerSearch_LocationSearch_input,
  input[id*="LocationSearch"],
  [class*="SearchInput--SearchInput"] {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  /* the legacy footer is a `div.Footer--container` (not a <footer> tag, so the
     footer rule below misses it) shipping white; and the ad placeholder frames
     ship a light grey backdrop. Darken both so nothing flashes bright. The
     footer's white fill comes from a CSS-in-JS rule injected AFTER our sheet (so
     it wins same-specificity ties); use the id-prefixed descendant form to
     out-rank it. */
  [id^="WxuFooter"] [class*="Footer--container"],
  [class*="Footer--container"] {
    background-color: var(--wx-chrome) !important;
  }
  [class*="adBackground"],
  [class*="combinedTopAds"],
  /* news/video articles carry a THIRD ad chrome family: a `position: fixed`, full-width
     100px sticky footer slot (`.ci-adhesion`) whose own fill is rgba(255,255,255,.5).
     Over the site's white page that is invisible; over our base it composites to a
     mid-grey #8b8d8e band pinned across the bottom of every article -- and the banner
     that fills it is narrower than the bar, so the grey shows on both sides. The slot
     ships `visibility: hidden` until an ad is served, so a scan (and a screenshot) of a
     session with an unfilled slot reports clean. */
  .ci-adhesion {
    background-color: var(--wx-surface-2) !important;
  }
  /* Once the slot is filled the ad stack adds a `ci-<id>-open` body class and a
     `.ci-<id>-open .ci-ad-<id> { background: #fff !important }` rule -- (0,2,0), so it
     beats the single-class rule above and the bar renders solid white across the
     viewport with the (narrower) creative floating in it. The numeric id rotates per
     creative; the `ci-ad-` prefix does not. */
  div[class*="ci-adhesion"][class*="ci-ad-"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the ad-disclosure label ("Advertisement") ships #6f7585 -- 3.68:1 on the
     darkened ad frame at 10px, an AA fail. It is a legal disclosure, so it must
     stay readable. The top ad slot draws its own label via a ::after content
     string (no text node), which no text audit can see. */
  .adLabel,
  [class*="BaseAd--adLabel"] {
    color: var(--wx-text-muted) !important;
  }
  [class*="combinedTopAdsPlaceholder"]::after {
    color: var(--wx-text-muted) !important;
  }
  /* the Almanac's two section headings ("Reported Conditions", "Historical
     Monthly Avg") are <th> cells inside <thead>; the generic `th` chrome fill
     below painted each of them as a black rectangle hugging the words, since
     they only span one column. weather.com leaves them transparent. */
  [class*="Almanac--tableTitle"] {
    background-color: transparent !important;
  }
  /* every Almanac row draws `border-bottom: 1px solid #dedede !important` from a
     [dir]-prefixed module rule at (0,2,0), which out-ranks the global
     `* { border-color }` at (0,0,0) -- so the card kept a bright white lattice.
     Re-match it one class deeper (0,2,1) to win. */
  [class*="Card--card"] tr[class*="Almanac--row"] {
    border-bottom-color: var(--wx-border) !important;
  }
  /* the calendar day numbers ship a #6f7585 module color (CalendarDateCell--date)
     -- fine on the original white grid but only ~3.4:1 on our dark card. Lift to
     the muted token for a comfortable read; the high/low temps stay as-is. */
  [class*="CalendarDateCell--date"] {
    color: var(--wx-text-muted) !important;
  }
  /* future / no-forecast day cells carry a small "Avg" caption
     (CalendarDateCell--label) shipping the same near-black #6f7585 module color as
     the date -- ~3.5:1 on our dark card (an AA fail for this small label), and left
     visibly dimmer than the lifted day numbers. Raise it to the muted token so the
     whole calendar grid reads at a consistent, legible muted light. */
  [class*="CalendarDateCell--label"] {
    color: var(--wx-text-muted) !important;
  }
  /* ...but the SELECTED day is a brand-blue #1b4de4 chip that weather.com labels in
     WHITE, and it carries `CalendarDateCell--date` too -- so the muted lift above landed
     grey-on-blue at 2.11:1 and the one cell the calendar is pointing at became the
     hardest to read. The chip is a real semantic fill, so keep it and put its white label
     back; compounded with the base class to out-rank it whatever the source order. */
  [class*="CalendarDateCell--date"][class*="CalendarDateCell--selected"] {
    color: #ffffff !important;
  }
  /* the legacy Monthly "Almanac" card title ships a hardcoded near-black #2b2b2b
     module color (Almanac--header) -> dark-on-dark and vanishes on our dark card;
     the record-year parentheticals ("(1934)" / "(1919)") ship a dim #6f7585
     (Almanac--recordYear) that only reads ~3.4:1 on the dark surface. Lift the
     title to primary light and the years to the muted token; the high/low temps
     and precip values keep their own colors. */
  [class*="Almanac--header"] {
    color: var(--wx-text) !important;
  }
  [class*="Almanac--recordYear"] {
    color: var(--wx-text-muted) !important;
  }

  /* the INTERNATIONAL locales (/de-DE/, /fr-FR/, ... -- the same domain, so inside this
     block) never migrated to the SPA: their Today page is the legacy Daybreak
     TodayDetailsCard, whose whole details grid paints BOTH the label and the value with
     the Helios ink #252422 -- Max/Min, Wind, Humidity, Dew point, Pressure, UV index,
     Visibility, Moon phase, eight rows at ~1.1:1 on our dark card, i.e. the entire block
     of numbers a forecast exists to show. The US routes never render this module (a US
     /weather/today redirects to the SPA), so sampling page TYPES on a US location cannot
     reach it. Both inks are achromatic natively (checked against the detached sheet), so
     one uniform lift restores the grid without inventing a hue. Wind and Pressure format
     their value through their own wrapper span, which carries the ink directly, so a
     matched rule beats the colour inherited from the row. */
  [data-testid="WeatherDetailsListItem"] [class*="WeatherDetailsListItem--label"],
  [data-testid="WeatherDetailsListItem"] [class*="WeatherDetailsListItem--wxData"],
  [data-testid="WeatherDetailsListItem"] [class*="Wind--windWrapper"],
  [data-testid="WeatherDetailsListItem"] [class*="Pressure--pressureWrapper"],
  /* the day-part table under it (Morgens / Nachmittags / Abends / Nachts) puts the
     chance-of-rain cell at #2b2b2b, so the one number in that row that varies is the
     one that disappears. */
  [class*="Column--precip"],
  /* and the legacy Air Quality page (/xx-XX/forecast/air-quality/l/...) ships the same
     ink on its "Air Quality Index" info link and on the "Source" title inside the
     legend popover. */
  [class*="AirQuality--moreDetailsText"],
  [class*="AirQuality--popoverTitle"] {
    color: var(--wx-text-2) !important;
  }
  /* the same locales' Daily Forecast writes each row's temperatures as
     `<TemperatureValue>29</> <span class="Column--tempLo">/<TemperatureValue>20</></span>`.
     Our TemperatureValue rule lifts both numbers, but the "/" between them is a bare text
     node on the tempLo wrapper, which keeps the Helios ink #252422 -- 1.2:1, so the row
     renders as two temperatures with nothing separating them. A separator, not data, so
     it takes the muted ink; the numbers keep their own colour. */
  [class*="Column--tempLo"] {
    color: var(--wx-text-muted) !important;
  }
  /* that page's per-pollutant concentration (19.36 ug/m3) is the dimmer #6f7585, which
     reads on the site's white card and 3.4:1 on ours -- an AA fail at 14px. */
  [class*="AirQualityText--measurement"] {
    color: var(--wx-text-muted) !important;
  }
  /* the same locales' news hubs (/de-DE/neuigkeiten/*, /de-DE/wissen/*) list their
     stories through the legacy `CollectionMediaList`, whose headline AND standfirst are
     both #252422 on the anchor's own wrapper -- so the entire article list rendered as
     ten thumbnails, ten timestamps and nothing else. The `Ellipsis--ellipsis` span that
     holds the words is a truncation utility with no colour of its own, so the two
     wrappers are what has to be lifted; the timestamp beside them is the dimmer #6f7585
     (3.4:1) and takes the muted token. */
  [class*="CollectionMediaList--title"] {
    color: var(--wx-text) !important;
  }
  [class*="CollectionMediaList--caption"] {
    color: var(--wx-text-2) !important;
  }
  [class*="CollectionMediaList--date"] {
    color: var(--wx-text-muted) !important;
  }

  /* EVERY legacy Helios icon (`Icon--icon--<hash>`) paints its glyph with the design
     system's INK -- #252422 or #2b2b2b -- reaching it three different ways: as a literal
     `fill` attribute, as a CSS `fill` on a path with no attribute at all, and as
     `currentColor` inherited from a wrapper our text rules never touch. On the site's
     white chrome that is correct ink; on ours it is 1.04-1.22:1, so the WHOLE icon set
     went invisible on every legacy route at once -- the left rail (Home / Today / Hourly /
     10 Day / Monthly / Radar / Video / Explore), the header magnifier and globe, the
     Monthly day-part table's Record High / Average High / Sunrise / Sunset marks, the
     calendar close button and the Cold-&-Flu allergen glyphs. Nothing is a background
     colour and nothing is text, so no bucket sees any of it.
     The COLOURED icons are safe from all three rules: `WxIcon--*` condition icons paint
     from `fill="var(--sun-lightning)"`-style ATTRIBUTES (so `path:not([fill])` skips
     them, and `color` is not in their chain), and the knockout Weather Company wordmark
     is excluded outright -- one of its paths is currentColor, so lifting it would bleach
     the mark. `Icon--lightTheme` is Helios for "drawn for a dark backdrop" and is
     natively WHITE (the play glyphs over video thumbnails), so it is put back; the header
     search magnifier carries that class but overrides it with its own ink, so it is
     re-darkened after. */
  svg[class*="Icon--icon"]:not([class*="logoIcon"]) {
    color: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    fill: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"] path[fill="#252422"],
  svg[class*="Icon--icon"] path[fill="#2B2B2B"],
  svg[class*="Icon--icon"] path[fill="#2b2b2b"] {
    fill: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"][class*="Icon--lightTheme"] {
    color: #ffffff !important;
  }
  svg[class*="Icon--icon"][class*="SearchInput--searchIcon"] {
    color: var(--wx-text-2) !important;
  }
  /* the international header's co-branding partner mark (`Cobranding--icon`, e.g. the
     de-DE "FOCUS online" wordmark) is an inline <svg> whose letters carry a LITERAL
     `fill="#000"` -- so the `path:not([fill])` lift above skips them and they vanish on
     the chrome. Only the black paths are re-inked; the partner's own brand colour on
     the remaining paths (the teal globe) is left as shipped. */
  svg[class*="Cobranding--icon"] path[fill="#000"],
  svg[class*="Cobranding--icon"] path[fill="#000000"],
  svg[class*="Cobranding--icon"] path[fill="black"] {
    fill: var(--wx-text) !important;
  }
  /* ...and two Helios icons are NOT ink: they inherit a CHROMATIC currentColor
     that the blanket lift above swallows, so their hue is the signal, not their
     legibility. The sunrise/sunset marks in the day-part card are #febc11 gold
     (matched to the gold sun on the arc right above them, which survives because
     its own paths carry fill attributes), and the Health & Activities row
     chevrons are the brand --Ocean #1b4de4, the same blue as the row's link
     text -- but #1b4de4 is 1.9:1 on the dark card, so that one takes the theme's
     link accent rather than its literal value. Both need the fill as well as the
     colour: the paths carry no fill attribute, so `path:not([fill])` above
     paints them directly and a matched rule beats an inherited one. */
  svg[class*="Icon--icon"][class*="TwcSunChart--sunIcon"],
  svg[class*="Icon--icon"][class*="TwcSunChart--sunIcon"] path {
    color: #febc11 !important;
    fill: #febc11 !important;
  }
  svg[class*="Icon--icon"][class*="HealthActivitiesListItem--icon"],
  svg[class*="Icon--icon"][class*="HealthActivitiesListItem--icon"] path {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* the Monthly day-detail's moon-phase glyph (DetailsTable--moonIcon) is a third such
     accent -- the one chromatic mark in a table of ink ones, so it is what says which row
     is the moon -- but unlike the two above its <path> carries NO fill attribute, so the
     blanket `svg[class*="Icon--icon"]:not(..):not(..) path:not([fill])` rule above matches
     it at (0,4,2). The fill selector has to carry that same tail plus one more simple
     selector or the glyph takes the accent colour while its path stays body-grey. */
  svg[class*="Icon--icon"][class*="DetailsTable--moonIcon"],
  svg[class*="Icon--icon"][class*="DetailsTable--moonIcon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* the legacy list pagination ("Zurück" / "Weiter" on the international news hubs)
     draws its chevrons brand-blue, the same ink as the "Weiter" label beside them; the
     disabled "Zurück" keeps that blue under the button's own opacity fade. Keyed to the
     Pagination class, NOT to `Icon--actionTheme`: that Helios theme class also sits on
     Monthly's precip / wind / day-detail marks, which resolve to plain ink natively. */
  svg[class*="Icon--icon"][class*="Pagination--arrows"],
  svg[class*="Icon--icon"][class*="Pagination--arrows"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* the sun-position marker on the sunrise/sunset arc is a plain
     `<circle r="12" fill="#FFF">` drawn UNDER the gold sun to punch the arc
     stroke out behind it. On the site's white card it is invisible; it has to
     track the card it sits on or it renders as a bright disc. */
  [class*="TwcSunChart"] circle {
    fill: var(--wx-surface) !important;
  }

  /* the legacy sign-in page separates the Google button from the email form with a
     literal `<span>or</span>` that carries a #ffffff fill and no class of its own (its
     only hook is the `SocialLogin--divider` parent) -- a bright chip punched through the
     hairline. Our text rules lift the word to body light, so it landed light-on-white at
     ~1.7:1 and the chip read as a blank white rectangle. Sink it into the page base so
     the divider reads as one continuous rule. */
  [class*="SocialLogin--divider"] span {
    background-color: var(--wx-base) !important;
    color: var(--wx-text-muted) !important;
  }
  /* the same form's footer separates "Terms of Use" from "Privacy Policy" with a
     literal `<span> | </span>` carrying the Helios ink #2b2b2b -- 13:1 on the site's
     white page, 1.24:1 on ours, so the two links run together. It is punctuation, not
     a link, so it takes the muted ink rather than the link colour. */
  [class*="MemberLoginForm--separator"] {
    color: var(--wx-text-muted) !important;
  }

  /* a few legacy link components pin their ink to the Helios `var(--Panther)`
     with `!important` at (0,1,0), which out-ranks the (0,0,1) anchor rule, so
     they render near-black while the plain links beside them stay blue: the
     /data-vendors in-paragraph opt-out links, and the section CTA that is the
     only control on /privacy-settings' "Manage Data Rights" block. `--Panther`
     also feeds legacy button FILLS and borders, so restore the link colour
     rather than remap the token, with a second simple selector to clear the
     site's !important. */
  [dir] [class*="DataVendors--anchorParagraphLink"],
  [dir] [class*="LinkSection--sectionLink"] {
    color: var(--wx-link) !important;
  }
  [dir] [class*="DataVendors--anchorParagraphLink"]:hover,
  [dir] [class*="LinkSection--sectionLink"]:hover {
    color: var(--wx-link-hover) !important;
  }
  /* three legacy page templates paint a full-page WHITE container of their own
     that no card / module / well selector reaches, so the whole page renders
     as our lifted light text on white: /privacy-settings (the consent control
     page, including its own inner header band), /data-rights (the DSR request
     accordion) and /storm-radar (the app promo page, whose feature sheet is
     1248x2891). All three sit directly on the page. */
  [class*="PrivacySettings--container"],
  [class*="PrivacySettings--container"] [class*="Header--headerSection"],
  [class*="DsrForm--dsrContainer"],
  [class*="PromoFeaturePage--featurePage"],
  [class*="PromoFeaturePage--featuresSection"] {
    background-color: var(--wx-base) !important;
  }
  [class*="PromoFeaturePage--featuresTitle"] {
    color: var(--wx-text) !important;
  }
  /* the Helios Disclosure accordion titles ship #2b2b2b. Inside the header's
     units panel they are already lifted by the ExpandableMenu rule; standalone
     -- as the four /data-rights sections -- nothing reached them. */
  [class*="Disclosure--Summary"] {
    color: var(--wx-text) !important;
  }
  /* the legacy plain-text button is the brand `--Ocean` #1b4de4, 2.74:1 on the
     page base (it reads 8:1 on the site's white). */
  [class*="Button--plainText"] {
    color: var(--wx-link) !important;
  }
  /* a disabled legacy button (`Button--disabled`, e.g. the news-list pagination's
     "Zurück"/"Back" on the first page) keeps the Helios ink at opacity .4 -- the fade is
     what marks it disabled, so only the ink is lifted; the opacity stays the site's.
     The `Button--primary` + `Button--disabled` pair (the /login submit, the /monthly
     "View" picker) is opacity 1 and marks disabled by its own #545351 fill + #cdcdcd
     ink (5.3:1) against the white-on-#252422 enabled state -- that pair stays native. */
  [class*="Button--disabled"]:not([class*="Button--primary"]) {
    color: var(--wx-text) !important;
  }
  /* the legacy solid CTA (`Button--primary`: Monthly's "View", the international Today
     card's "Nächste 48 h" / "Siehe details", the /login and /data-rights submits) is the
     Helios ink #252422 under a white label -- within 1.05:1 of the card it sits on, so the
     plate vanishes and only its DISABLED sibling (#545351 fill, kept native above) still
     reads as a button: the pair inverts. Invert the enabled state the way the chart tabs
     and the units radiogroup are inverted: a light plate with chrome ink. Two attributes
     so it out-ranks the anchor rule on the `<a>` form and the ExpandableMenu lift; the
     Helios icon rules match an inner glyph directly, so it is re-pointed with the label. */
  [class*="Button--primary"]:not([class*="Button--disabled"]) {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  [class*="Button--primary"]:not([class*="Button--disabled"]) svg[class*="Icon--icon"],
  [class*="Button--primary"]:not([class*="Button--disabled"]) svg[class*="Icon--icon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-chrome) !important;
    fill: var(--wx-chrome) !important;
  }

  /* /mission's "Better Decisions" panels drop to a pure-black heading + legal
     disclaimer in their lower sections (the upper ones are brand blue). */
  [class*="BetterDecisions--heading"] {
    color: var(--wx-text) !important;
  }
  [class*="BetterDecisions--disclaimerText"] {
    color: var(--wx-text-muted) !important;
  }

  /* sub-nav pill row sits in a white rounded bar */
  [data-testid="subnavigation"] a,
  [data-testid="subnavigation"] button {
    color: var(--wx-text-2) !important;
  }
  [data-testid="subnavigation"] a:hover {
    color: var(--wx-text) !important;
  }
  /* the forecast-type pill row (Today / Hourly / 10 Day / ...) marks the CURRENT page
     with `text-blue-500` (#3a61cc) on a grey pill. The rule above repainted it plain
     light -- and the inactive tabs ship `text-gray-900`, which our text rules ALSO
     lift to the same light -- so every tab in the strip rendered identically and the
     selected forecast lost its marker. Give the current tab the link accent back. */
  [data-testid="subnavigation"] [aria-current="page"] {
    color: var(--wx-link) !important;
  }

  /* ---- horizontal-scroll fade overlays (the white "more →" gradients) --- */
  /* The forecast-type nav (Today / Hourly / 10 Day / ...) and the chart tab
     strip (Overview / Temperature / Feels Like / Precipitation / Wind / Wind
     Gust) are horizontally-scrollable rows that paint a left/right edge fade as
     a `pointer-events-none absolute` overlay with a `from-white` Tailwind
     gradient (`bg-gradient-to-r/-l from-white via-white`). It's a
     BACKGROUND-IMAGE, not a background-color, so a bg-color audit is blind to
     it -- and it renders as a bright white bar over the dark strip. Neutralise
     the white ORIGIN of the gradient (the `from-white`/`via-white` stops resolve
     `--color-white` / `--tw-gradient-*`) so every such fade blends into the page
     base instead, regardless of direction. */
  [class*="pointer-events-none"][class*="from-white"],
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"] {
    --color-white: var(--wx-base) !important;
    --tw-gradient-from: var(--wx-base) !important;
    --tw-gradient-via: var(--wx-base) !important;
  }
  /* the chart tab strip's fades are authored as literal
     `linear-gradient(to right/left, #fff 36px, transparent)` (not from-white),
     so also override the whole image to the page base. An edge fade is anchored
     to ONE side only (`inset-y-0 left-0 w-32` / `inset-y-0 right-0 w-32`); an
     overlay anchored on BOTH sides is a full-width layer, not a fade -- the radar
     map's control layer (legend strip, layer pills, floating buttons) is
     `inset-y-0 left-0 right-0` at rest and `inset-y-0 right-0 left-[370px]`
     while the Map Menu is open, ships no background, and must never get this
     image or the basemap is veiled in a dark gradient. The exclusion is the
     OTHER side's prefix (`left-`/`right-`), not `left-0`, so the open-menu
     `left-[370px]` variant stays excluded too. */
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"][class*="left-0"]:not([class*="right-"]) {
    background-image: linear-gradient(to right, var(--wx-base) 36px, rgba(20, 24, 29, 0) 100%) !important;
  }
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"][class*="right-0"]:not([class*="left-"]) {
    background-image: linear-gradient(to left, var(--wx-base) 36px, rgba(20, 24, 29, 0) 100%) !important;
  }
  /* the LEGACY equivalent is the Helios Carousel arrow button, whose own
     background IS the fade (`linear-gradient(90deg, transparent, #fff)`) -- an
     89x46 white blob at the end of every scrollable strip. The Carousel is a
     card component, so the fade resolves to the card surface. The site writes
     it `!important` from a `[dir="ltr"] .class` rule, so the override needs a
     third simple selector to out-rank it. */
  [dir] [class*="Carousel--arrowContainer"][class*="Left"] {
    background-image: linear-gradient(270deg, rgba(28, 33, 40, 0), var(--wx-surface)) !important;
  }
  [dir] [class*="Carousel--arrowContainer"][class*="Right"] {
    background-image: linear-gradient(90deg, rgba(28, 33, 40, 0), var(--wx-surface)) !important;
  }

  /* ---- Tailwind surface utilities (stable, non-hashed) ----------------- */
  /* These ship literally as bg-white / bg-gray-100 / bg-gray-50 on content
     wells, cards and tiles. Excluded: maps / svg / canvas (handled below). */
  .bg-white,
  .bg-card,
  .bg-popover,
  [data-slot="card"],
  [data-slot="popover"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  .bg-gray-100,
  .bg-gray-50,
  .bg-neutral-100,
  .bg-slate-100,
  .bg-muted,
  .bg-secondary,
  .bg-accent {
    background-color: var(--wx-surface-2) !important;
  }
  /* the article's "Get More of Our News on Google" callout floats its `bg-gray-50` card on
     a warm-grey drop shadow written as an arbitrary utility. A light shadow composited
     over the dark article body is a halo, not a shadow, so it takes a black one of the
     same geometry. */
  [class*="shadow-[0_3px_20px_0_rgba(181,171,162,0.5)]"] {
    box-shadow: 0 3px 20px 0 rgba(0, 0, 0, 0.55) !important;
  }
  /* -200/-300 are one step STRONGER than -100 on the site's white page, so one step
     LIGHTER than the -100 surface here. They are rail/track fills, not card surfaces
     (the Cold & Flu extended-forecast scrubber rail, switch tracks), which is why they
     take the border tone rather than an elevated surface. */
  .bg-gray-200,
  .bg-gray-300,
  .bg-neutral-200,
  .bg-neutral-300 {
    background-color: var(--wx-border) !important;
  }
  /* Tailwind's `bg-black/N` veils are the design system's "subtle plate": a few percent
     of BLACK over a white page. On our dark surfaces they are invisible, which is what
     emptied the chart tab strip's unselected pills and the video-thumbnail placeholders.
     Mirror the veil to white so a plate keeps the weight the site gave it. Only the LOW
     alphas are plates -- /30 and up are scrims over photos and must stay black.
     `[class~=]` matches a whole class token, so `bg-black/5` cannot also catch
     `bg-black/50`. */
  [class~="bg-black/5"],
  [class~="bg-black/8"],
  [class~="bg-black/10"] {
    background-color: rgba(230, 237, 243, 0.06) !important;
  }
  [class~="hover:bg-black/5"]:hover,
  [class~="hover:bg-black/14"]:hover,
  [class~="hover:bg-black/20"]:hover,
  [class~="hover:bg-black/[0.12]"]:hover {
    background-color: rgba(230, 237, 243, 0.12) !important;
  }
  [class~="active:bg-black/5"]:active,
  [class~="active:bg-black/[0.2]"]:active {
    background-color: rgba(230, 237, 243, 0.2) !important;
  }
  /* the MOBILE header nav drawer paints each expanded section's sub-item list
     (Weather Forecasts -> Today / Hourly / 10 Day, Radar & Maps -> ..., etc.) as a
     `<ul>` carrying the Tailwind ARBITRARY class `bg-[#ebecee]` -- a light grey none
     of the named `.bg-gray-*` utilities above match. Our link/text rules already lift
     the sub-item labels (text-gray-*) to light, so on the #ebecee list they rendered
     light-on-light (~1.3:1) and every expanded submenu was unreadable. Only appears
     after a section is expanded on a narrow viewport, so a load-time scan never sees
     it. Darken the list to the elevated surface; the lifted labels then read. */
  [class*="bg-[#ebecee]"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the NEW SPA location-search flyout (the "New location selector") ends its
     Recents list with a "Favorite places, at your fingertips" sign-up upsell
     button that ships Tailwind's LIGHT brand tint `bg-brand-100` (#cbdef0) --
     a different hook from the LEGACY header's LocationsUpsell card handled far
     below. Our text rules lift its title/subtitle to light, so on the pale-blue
     fill it rendered light-on-light (~1.5:1) and the CTA nearly vanished on the
     otherwise-dark dropdown. Darken the PALE brand tints to the elevated surface so the
     lifted copy reads; the SATURATED brand blues are real fills and are left untouched.
     The pale tints are --color-brand-50 / -100 (#cbdef0) plus the alpha variants Tailwind
     compiles from them: `bg-brand-100/30` is a 30% veil whose class TOKEN is literally
     `bg-brand-100/30`, so the plain `.bg-brand-100` class selector does not match it --
     hence the substring form. --color-brand-200 is NOT a tint: it is #679ced, the same
     mid-blue weather.com fills the Hourly wind-gust pills with (under white text), so
     collapsing it to grey erased a real fill; it now keeps its own colour like -300/-400
     do, and whichever label utility the site puts on it stays readable. */
  .bg-brand-50,
  .bg-brand-100,
  [class*="bg-brand-100/"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* translucent white veils used as gradient/scrim fills over photos */
  .bg-white\/75,
  .bg-white\/80,
  .bg-white\/90 {
    background-color: rgba(28, 33, 40, 0.85) !important;
  }
  /* dark utility surfaces the app already uses (location pill, etc.) keep a
     consistent dark tone matching the chrome */
  .bg-gray-900,
  .bg-black {
    background-color: var(--wx-chrome) !important;
  }
  /* ...but the Sign-in CTA is a `bg-gray-900` plate that SITS ON the chrome, in both of
     the SPA's two header layouts, and each lost it a different way:
     - in the left rail it is an `<a>`, so the rail's own
       `[data-testid="sidebar-navigation"] a { background: transparent }` blanked it
       outright and the only account entry point rendered as bare text between the nav
       links;
     - at <=md it is a `<button>` in the `<header>`, where the rule above resolves it to
       --wx-chrome -- the exact colour of the header behind it, so the plate vanished
       just the same.
     Neither shows up in any bucket: a dark control on a dark bar reads fine, it just
     stops being a button. Give the CTA the elevated surface so its plate reads against
     the chrome; the location pill already resolves there, so this is a no-op for it. */
  [data-testid="sidebar-navigation"] a.bg-gray-900,
  [data-testid="sidebar-navigation"] a.bg-black,
  header .bg-gray-900,
  header .bg-black {
    background-color: var(--wx-surface) !important;
  }
  [data-testid="sidebar-navigation"] a.bg-gray-900:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* Tailwind HOVER-VARIANT grey fills (hover:bg-gray-100 / -200 / -50) compile to
     variant-prefixed class names (`hover:bg-gray-100`) that our plain .bg-gray-100
     rule doesn't match. The forecast-type nav tabs (Today / Hourly / 10 Day /
     Monthly / Gardening / ...) ship hover:bg-gray-100, so hovering a tab flashed a
     bright #f2f2f2 pill under our lifted light text -> light-on-light and the tab
     label vanished. Remap the hovered fill to the elevated dark surface so the
     hovered tab stays legible (the active tab already reads dark). */
  [class*="hover:bg-gray-100"]:hover,
  [class*="hover:bg-gray-200"]:hover,
  [class*="hover:bg-gray-50"]:hover,
  [class*="hover:bg-neutral-100"]:hover,
  [class*="hover:bg-neutral-200"]:hover {
    background-color: var(--wx-surface-2) !important;
  }
  /* `hover:bg-white` is the same family one step further: the video page's outlined
     "Transcript" pill is `bg-transparent border-gray-500 hover:bg-white`, so hovering it
     filled PURE #fff under our lifted --wx-text-2 label -- 1.42:1, the word and its
     chevron gone. Only a native-vs-themed hover diff sees it; at rest the button is
     correct. The site's move is transparent -> a full-contrast plate, so match that
     intent with the component border tone rather than the near-base surface, which
     against #14181d would read as no change at all.
     The chart tab strip carries `hover:bg-white` too, but pairs it with the `!`-suffixed
     `hover:!bg-gray-900`, whose layered !important outranks this unlayered one -- the
     selected tab keeps the light pill the --color-gray-900 remap gives it. */
  [class~="hover:bg-white"]:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* A control that is ALREADY a grey fill at rest (bg-gray-100) and steps one shade
     down on hover collapses to a no-op above, because both the rest rule and the hover
     rule land on --wx-surface-2 -- the /hourbyhour/day-N prev/next day pills lost their
     fill change that way. Step them to the component border tone instead so the hover
     is a real shade change. Needs three classes to out-rank both rules. */
  [class*="bg-gray-100"][class*="hover:bg-gray-200"]:hover,
  [class*="bg-gray-50"][class*="hover:bg-gray-100"]:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* the same light greys also arrive through the FOCUS and ACTIVE variants, which the
     hover list above does not match: `focus-visible:bg-gray-100` is the keyboard
     indicator on the rail items and the video-category tabs, `active:bg-gray-200` the
     press state on most pills -- both painted #f2f2f2 under our lifted light text.
     Matched on plain `:focus`, a superset of `:focus-visible` and the CSS2 form the
     userstyles.org parser accepts.
     `active:bg-[#E6E6E6]` is the arbitrary-hex sibling, on the hero CTAs ("Read more" /
     "Watch") that ship `bg-white text-gray-900` and get NO hover state -- the press is
     their only feedback. It cannot flash light here: our unlayered `.bg-white` !important
     already outranks that layered utility, which is exactly why the control ends up with
     no press response at all unless it is restated. */
  [class~="focus:bg-gray-100"]:focus,
  [class~="focus-visible:bg-gray-100"]:focus,
  [class~="active:bg-gray-100"]:active,
  [class~="active:bg-gray-200"]:active,
  [class~="active:bg-gray-300"]:active,
  [class~="active:bg-[#E6E6E6]"]:active,
  [class~="max-sm:active:bg-gray-100"]:active {
    background-color: var(--wx-surface-2) !important;
  }

  /* ---- segmented tab strips --------------------------------------------- */
  /* The chart tab strip (Overview / Temperature / Feels Like / ... on Hourly) marks its
     SELECTED tab with `!bg-gray-900`: a Tailwind `!`-suffixed utility, so its !important
     sits inside the utilities cascade LAYER and beats our unlayered `.bg-gray-900`
     override whatever the specificity. The pill therefore kept the raw #252422 token,
     which is the same luminance as our card -- and with the unselected `bg-black/5`
     plates invisible too, the whole control read as twelve identical labels with no
     sign of which chart was open. `!bg-gray-900` resolves `var(--color-gray-900)`, and
     variable resolution is layer-agnostic, so redefining the token ON the tab computes
     our value while their rule still "wins" the cascade. The site's own move is to
     invert the selected pill against the page, so invert it the other way here: a light
     plate with chrome-dark ink.
     Keyed to the `!` utility rather than to aria-selected, because the LEGACY
     `role="tab"` unit picker (deg-F / deg-C / Hybrid) is a transparent tab marked by an
     underline -- dark ink there would erase the label. */
  [role="tab"][class~="!bg-gray-900"] {
    --color-gray-900: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  /* the header "More" drawer's UNIT picker is the same control one component over: a
     `role="radiogroup"` whose track is `bg-gray-100` and whose CHECKED option is a plain
     (un-`!`) `bg-gray-900` pill. Both utilities are remapped above, and they land one
     step apart -- the track on --wx-surface-2, the pill on --wx-chrome -- so the selected
     unit's plate reads 1.1:1 against the track it sits in and the chip disappears; only
     the white-vs-muted label was left to say which unit is active. The control only
     exists once the drawer is opened, so no load-time scan renders it. Invert it the way
     the chart tabs above are inverted: a light plate with chrome ink. Keyed to
     aria-checked so the unchecked options keep the transparent track. */
  [role="radio"][aria-checked="true"][class~="bg-gray-900"] {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  /* the video-category strip (Viral Videos / Latest Weather / News / ...) is `md:hidden`,
     so it exists ONLY below 768px -- a desktop scan never renders it. It fills its
     UNSELECTED tabs through the state variant `data-[state=inactive]:bg-gray-100`, a
     class token no plain `.bg-gray-*` selector matches, so they stayed #f2f2f2 pills
     under our lifted light labels: light-on-light, every inactive category unreadable.
     The variant class is in the list in BOTH states, so it must be paired with the state
     attribute or every tab takes the fill. Muting the inactive label restores the
     weight the site gets from #f2f2f2 against the active navy pill. */
  [class~="data-[state=inactive]:bg-gray-100"][data-state="inactive"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class~="data-[state=inactive]:text-gray-600"][data-state="inactive"] {
    color: var(--wx-text-muted) !important;
  }
  /* the focus RING is a box-shadow, so the blanket border reset never reached it -- but
     weather.com rings in #3a61cc, 5.5:1 on its white page and 2.9:1 on ours, under the
     3:1 a non-text indicator needs. The ring colour is a custom property, so redefining
     it on the ringed element is enough. */
  [class*="ring-blue-500"] {
    --tw-ring-color: var(--wx-link) !important;
  }
  /* ...and the app's OTHER keyboard indicator is an `outline-blue-600` outline,
     a plain `outline-color` no ring token feeds: #204794 is 10:1 on the site's
     white page and 1.73:1 on the base, so Tab moves an invisible marker. The
     outline's width and style only exist in the focus-visible state, so
     recolouring the utility unconditionally touches nothing at rest. */
  [class*="outline-blue-500"],
  [class*="outline-blue-600"],
  [class*="outline-blue-700"] {
    outline-color: var(--wx-link) !important;
  }

  /* ---- cards / modules / wells ----------------------------------------- */
  [data-slot="card"],
  [data-slot="card-header"],
  [data-slot="card-content"],
  [data-testid="current-conditions"],
  [data-testid="current-widgets"],
  [data-testid="daily-forecast"],
  [data-testid="next-48-hours"],
  [data-testid="HealthAndActivitiesModule"],
  [data-testid="AirQualityIndex"],
  [data-testid$="Module"],
  [data-testid$="-container"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [data-slot="card-header"] {
    background-color: transparent !important;
  }

  /* ---- text ------------------------------------------------------------- */
  h1, h2, h3, h4, h5, h6,
  .text-gray-900,
  .text-black,
  .text-card-foreground,
  .text-foreground,
  b, strong {
    color: var(--wx-text) !important;
  }
  p, li, dt, dd, label, figcaption, small,
  .text-gray-700,
  .text-gray-800,
  .text-neutral-800 {
    color: var(--wx-text-2) !important;
  }
  /* article and product-review bodies are mostly lists, and their BULLETS and ORDERED
     NUMBERS come from `::marker`, which no `li { color }` rule reaches -- the marker keeps
     the site's #252422 ink at 1.04:1 while the list text beside it is lifted, so a
     30-bullet page renders as text with no bullets and a numbered list loses its numbers
     entirely. A pseudo-element with no text node: invisible to every colour walk. */
  li::marker {
    color: var(--wx-text-2) !important;
  }

  /* muted / secondary greys the app uses for metadata + captions */
  .text-gray-400,
  .text-gray-500,
  .text-gray-600,
  .text-neutral-500,
  .text-text-secondary,
  .text-muted-foreground,
  [class*="text-[#6f7585]"],
  [class*="text-[#8d8d8d]"] {
    color: var(--wx-text-muted) !important;
  }

  /* weather.com colors most neutral text via near-black inline rgb -- lift
     those so they don't go dark-on-dark, while saturated hues stay below. */
  [style*="color: rgb(37, 36, 34)"],
  [style*="color:#252422"],
  [style*="color: rgb(55, 55, 53)"] {
    color: var(--wx-text-2) !important;
  }
  [style*="color: rgb(103, 103, 103)"],
  [style*="color: rgb(141, 141, 141)"] {
    color: var(--wx-text-muted) !important;
  }
  /* the Sunrise / Sunset markers in the Hourly graph (and the Today outlook
     strip) carry a SEMANTIC inline colour on both the label and its icon: a warm
     burnt-orange rgb(37,36,34)-style sunrise (rgb(203,74,20)) and a dusky-mauve
     sunset (rgb(163,81,112)). Our `.text-gray-900` !important rule flattened both
     to plain light, so sunrise/sunset read like every other hour label and lost
     the warm/cool signal. The native hues are too dark for our surface (~2.2:1),
     so restore a LIGHTENED warm tint for sunrise and a cool mauve for sunset --
     the icon fill is currentColor, so setting the colour recolours it too. */
  [style*="color: rgb(203, 74, 20)"] {
    color: #ec9a5c !important;
    -webkit-text-fill-color: #ec9a5c !important;
  }
  [style*="color: rgb(163, 81, 112)"] {
    color: #d891ac !important;
    -webkit-text-fill-color: #d891ac !important;
  }
  /* the precipitation-chance percentages plotted on the Today's Outlook hourly
     graph carry an inline SEMANTIC teal (rgb(63,81,...)->rgb(63,149,178)) on both
     the label and, via -webkit-text-fill-color, its rendered glyphs -- weather.com's
     rain tint. They also ship the `text-gray-900` class, so our `.text-gray-900`
     !important flattened them to plain light and the "45%" under a storm icon read
     like any neutral label, losing the rain signal (the Sunrise/Sunset markers in
     the same strip were restored just above, but this teal was missed). Restore a
     lightened rain teal that keeps the identity and passes AA on the dark card. */
  [style*="color: rgb(63, 149, 178)"] {
    color: #5cb3d1 !important;
    -webkit-text-fill-color: #5cb3d1 !important;
  }

  /* ---- Air Quality page (All Pollutants list + AQI status heading) ------ */
  /* The Air Quality page colors its key headings with a NEAR-BLACK Tailwind
     arbitrary token `text-[#2b2b2b]` (NOT a saturated AQI-category hue here):
     - the pollutant NAME labels in the "All Pollutants" list
       ([data-testid="PollutantName"]) -- "O3 (Ozone)", "CO (Carbon Monoxide)",
       "NO2 (Nitrogen Dioxide)", "PM10", "PM2.5", "SO2" ...
     - the big AQI status heading next to the gauge
       ([data-testid="AirQualityCategory"]) -- "Good" / "Moderate" / "Unhealthy".
     Both render #2b2b2b -> dark-on-dark and vanish. Lift to primary light so
     they read; these are neutral near-black tokens, not colored AQI codes, so
     no semantic hue is lost (the colored gauge arc + status DOT keep theirs). */
  [data-testid="PollutantName"],
  [data-testid="AirQualityCategory"],
  [class*="text-[#2b2b2b]"],
  [class*="text-[#252422]"] {
    color: var(--wx-text) !important;
  }
  /* the per-pollutant severity word ("Good"/"Moderate") ships text-[#6f7585]
     (a muted grey, already remapped above) -- pin it via its stable testid too
     so the row status stays a legible muted light regardless of class rotation. */
  [data-testid="AirQualitySeverity"] {
    color: var(--wx-text-muted) !important;
  }
  /* the Health & Activities donut value (Cold & Flu "98%", health indices) is a
     [data-testid="DonutChartValue"] node whose color is a near-black #424a50 ->
     dark-on-dark. (On the AQI page it sits inside [data-testid="DonutChart"] and
     was already lifted; the Cold-&-Flu/health donut carries the testid directly,
     so pin both the HTML color and the SVG <text> fill.) */
  [data-testid="DonutChartValue"],
  [data-testid="DonutChartValue"] text,
  [data-testid="DonutChartValue"] tspan {
    color: var(--wx-text) !important;
    fill: var(--wx-text) !important;
  }

  /* ---- site-wide near-black text tokens (header, content strip, footer) -- */
  /* These surfaces appear on EVERY page (Allergies / Cold-&-Flu siblings most
     visibly), colored via hashed CSS-module classes that resolve to near-black
     tokens (#252422 / #2b2b2b) -> dark-on-dark once the surface is darkened:
     - the header language / unit display ("US" / "°F")
     - the "More from weather.com" content-strip article titles
     - the footer privacy links ("Cookie Settings", "Privacy Policy" ...).
     Lift to a readable light; the content-strip thumbnails + colored data are
     untouched (this only recolors the title/label text). */
  [data-testid="languageSelectorStatus"],
  [class*="LanguageSelector--unitDisplay"],
  [class*="LanguageSelector--LanguageSelectorStatus"],
  [data-testid="ContentMediaTitle"],
  [class*="ContentMedia--listItemTitle"],
  [class*="MediaObject--mediaCaptionCTA"] {
    color: var(--wx-text) !important;
  }
  [class*="PrivacyLinks"],
  [class*="PrivacyLinks"] a,
  footer [class*="Footer--link"] {
    color: var(--wx-text-2) !important;
  }
  [class*="PrivacyLinks"] a:hover,
  footer [class*="Footer--link"]:hover {
    color: var(--wx-link-hover) !important;
  }
  /* content-strip / news-teaser article SUMMARY paragraphs ship a near-black
     #252422 via MediaObject--mediaCaption -> dark-on-dark once the card is dark
     (the headline + "Watch Now" CTA were already lifted, but the description body
     stayed invisible -- seen on the Cold & Flu "Your Daily Flu Risk..." teaser).
     Lift the caption body to readable light. The mediaCaptionCTA link keeps its
     own treatment (matched more specifically above / by the link rules). */
  [class*="MediaObject--mediaCaption"]:not([class*="mediaCaptionCTA"]) {
    color: var(--wx-text-2) !important;
  }
  /* the same teaser's dateline is its own #686c74 -- a grey the muted-token list
     does not carry, and 3.07:1 at 14px on the card. */
  [class*="MediaObject--mediaPublishDate"] {
    color: var(--wx-text-muted) !important;
  }
  /* the content-media / promo thumbnails (news strips, "Stay Safe" fallback,
     "Spring Is Here", sidebar teasers) paint a LIGHT #f3f3f3 -> #e5e5e5 gradient
     placeholder (Image--gradient) behind the lazy-loaded <img>. It's a
     background-IMAGE (a bg-color audit is blind to it), and until the thumbnail
     paints -- or on image-less promo fallbacks -- it renders as a bright box on
     the dark card (glaring across the Monthly / Allergy / radar content strips).
     Darken the placeholder gradient so the load state reads dark; the real <img>
     paints over it unchanged (imgs already keep a transparent bg below). */
  [class*="Image--gradient"] {
    background-image: linear-gradient(135deg, var(--wx-surface-2), var(--wx-surface)) !important;
  }

  /* the SPA content hubs (/news, /health, /travel, /pets, /home-garden, ...)
     ship the SAME placeholder as an INLINE `background:` shorthand with no
     class, on the card <div> or directly on the <img>. Match the literal
     attribute text -- an inline shorthand is beaten by an !important
     background-image, and the loaded thumbnail still paints over it. An
     attribute selector matches the RAW attribute value, so the hex and rgb()
     spellings of the same gradient are two different selectors and both have to
     be listed. */
  [style*="linear-gradient(135deg, rgb(243, 243, 243)"],
  [style*="linear-gradient(135deg, #f3f3f3"],
  [style*="linear-gradient(135deg, #F3F3F3"] {
    background-image: linear-gradient(135deg, var(--wx-surface-2), var(--wx-surface)) !important;
  }
  /* the legacy Classic Maps pages (/maps/*) size every map thumbnail with an
     `--imagePlaceholder--` wrapper filled #dee0e3, so a 613x345 light plate
     stands behind the primary map (and one per collection tile) until the
     raster arrives. The map raster itself paints over it untouched. */
  [class*="imagePlaceholder"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* legacy section breaks are <hr> with zero border and a light #dedede FILL,
     so the blanket border reset never reaches them. */
  hr {
    background-color: var(--wx-border) !important;
  }

  /* ---- temperature scale (semantic, NEUTRAL ends only) ------------------ */
  /* weather.com renders the temperature readouts with NEUTRAL colors: the high
     in a near-black (rgb(37,36,34)) and the low in a grey (rgb(103,103,103)) --
     NOT a saturated hue scale. Both go dark-on-dark, so we lift them: the high
     to a warm light tone (still reads as "high"), the low to a cool light tone.
     Any genuinely colored value (alert reds, AQI/UV codes) is preserved. */
  [data-testid="TemperatureValue"] {
    color: var(--wx-text) !important;
  }
  /* the dimmer (low / secondary) temperature -> cool light. weather.com marks it
     two different ways and only one of them is an inline style: the SPA daily rows
     wrap the low in a `text-gray-500` span (the high is `text-gray-900` + bold),
     while older markup carries an inline rgb(103, 103, 103). Both forms have to be
     listed or the low and the high resolve to the same light and the pair reads
     as one value. The class form must be TWO classes deep to out-rank the
     TemperatureValue lift above, which is a direct declaration on the child. */
  [data-testid="daily-forecast"] [data-testid="TemperatureValue"][style*="103"],
  [data-testid="daily-forecast"] span[style*="rgb(103, 103, 103)"] [data-testid="TemperatureValue"],
  span[style*="rgb(103, 103, 103)"] > [data-testid="TemperatureValue"],
  span.text-gray-500 > [data-testid="TemperatureValue"] {
    color: #7fb4e6 !important;
  }
  /* the "Feels Like" widget paints a SOLID disc whose inline background-color is
     the feels-like temperature color on weather.com's scale (a pale near-white
     tint at mild temps, a saturated hue when hot) -- a div.rounded-full carrying
     an inline `background-color: rgb(...)`. That semantic fill is preserved, but
     our global TemperatureValue->light rule above then renders the centered value
     light-on-light and it vanishes inside the disc. weather.com itself centers a
     DARK value (text-gray-900) on this disc across the whole scale, so restore a
     dark, readable value HERE only (the disc keeps its own data color). */
  .rounded-full[style*="background-color"] [data-testid="TemperatureValue"] {
    color: #14181d !important;
    -webkit-text-fill-color: #14181d !important;
  }
  /* the precipitation-chance percentages in the Today / 10-Day forecast lists ship
     weather.com's precip blue as a Tailwind arbitrary token text-[#007ea8] -- a
     SEMANTIC rain color that reads ~4.6:1 on the original white card but drops to
     ~3.5:1 on our dark surface (a dark-on-dark fail for this 14px label). Lift to a
     lighter precip blue that keeps the rain identity while passing AA; the colored
     precip icons keep their own hues. */
  [class*="text-[#007ea8]"],
  [class*="text-[#007EA8]"] {
    color: #45a8db !important;
  }
  /* the SAME percentages switch to a muted grey `text-[#9ca3af]` when the
     chance of rain is negligible -- that grey/blue pair is the signal. Our
     generic `p` rule repainted the grey ones as body text, so a 3% hour and a
     53% hour read at the same weight (only the hue differed). Keep the muted
     ones muted. */
  [class*="text-[#9ca3af]"] {
    color: var(--wx-text-muted) !important;
  }

  /* the "BREAKING" kicker on news cards is the only place weather.com uses the
     severe-alert red as TEXT rather than as a banner fill: `text-[var(--color-alert-
     severe)]` = #ba0d00, which reads 6.5:1 on the site's white card but collapses to
     2.66:1 on our base -- an AA fail at its 10px size, and the one label whose whole
     job is to shout. Lift it to a brighter red that keeps the alert identity and
     passes AA; the alert BANNER (bg-alert-severe with white text) is untouched. */
  [class*="text-[var(--color-alert-severe)]"] {
    color: #f4695c !important;
  }

  /* ---- links / accent --------------------------------------------------- */
  a,
  a:visited,
  .text-blue-500,
  .text-blue-600,
  .text-blue-700,
  /* the video-playlist rail marks the active item with brand-blue "Now Playing" /
     "Next Up" kicker <p>s carrying the named `text-brand-light` utility (#3a61cc).
     The generic `p` text rule flattened them to body grey, so the active clip read
     like every other title and lost its accent. #3a61cc is only ~2.9:1 on our base,
     so restore the theme's link blue (as the subnav/rail active markers do). */
  .text-brand-light {
    color: var(--wx-link) !important;
  }
  a:hover,
  a:focus {
    color: var(--wx-link-hover) !important;
  }
  /* article bodies wrap their in-text cross-links in <strong> ("(MORE: <headline>)").
     `b, strong` and `a` are both (0,0,1) !important, but the anchor rule colours the
     <a> while `b, strong` matches the CHILD directly -- a matched rule always beats an
     inherited value, so every bolded link lost its accent and read as plain bold prose
     while the plain-text links beside it stayed blue. Inherit the anchor's colour so a
     bolded link looks like a link, including where the anchor is white-on-a-fill. */
  a strong,
  a b {
    color: inherit !important;
  }
  /* the legacy layout's SECTION HEADINGS ("Sun & Moon >", "Travel Far, Travel Often >",
     "We Love Our Critters >") are `a.Button--default` wrapping an <h2>. weather.com's only
     hover feedback on them is fading the anchor's ink to 80% alpha, which the <h2>
     inherits -- but our `h1..h6` rule matches that heading DIRECTLY, and a matched rule
     beats an inherited value, so under the theme these links had NO hover state at all
     (no colour change, no underline, no opacity shift). A load-time scan cannot see this;
     only a native-vs-themed hover diff can. Brighten the heading instead of dimming it,
     which is the dark-surface equivalent of the site's fade. Exactly the five legacy
     section headers carry a heading inside a Button--default anchor -- the article-card
     titles are `a.mediaLink` and keep their own underline-on-hover. */
  a[class*="Button--default"]:hover h1,
  a[class*="Button--default"]:hover h2,
  a[class*="Button--default"]:hover h3 {
    color: var(--wx-link-hover) !important;
  }
  /* the /video rail's card titles are <h2 class="text-gray-900 group-hover:text-[#1B4DE4]">:
     the whole card is the `.group`, and hovering it is the rail's ONLY affordance. That
     class is a Tailwind GROUP-variant, so it compiles to a variant-prefixed name no plain
     selector reaches, while `h1..h6 / .text-gray-900` above matches the same <h2> with
     !important -- so all ten titles stayed white and hovering a card changed nothing.
     Scope the restore to the hovered .group: the variant class sits in the class list at
     rest too, so unconditionally it would paint every title blue. #1b4de4 itself is 2.7:1
     on our base, so use the theme's hover blue as the headings above do. */
  .group:hover [class*="group-hover:text-[#1B4DE4]"] {
    color: var(--wx-link-hover) !important;
  }
  /* weather.com's solid brand CTAs ("See Details", ...) are `bg-brand-400`/`-300`
     (#0d142a / #204794 -- dark navies we deliberately leave alone) labelled with
     `text-primary-foreground`, i.e. near-white. The `a` rule above repainted that
     label link-blue, so a filled primary button read like an inline text link. The
     paler brand tints (50/100/200) are handled far above as light surfaces; these
     two saturated ones keep the site's white label. */
  .bg-brand-300,
  .bg-brand-400 {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* The Today "Next 10 Days" CTA is an `<a data-testid="next-48-hours">` -- the SAME
     testid the surrounding card carries, so the card rule above (0,1,0) painted the
     button --wx-surface and the plate vanished into the card it sits on: the CTA read
     as bare text. Restating the brand fills here (later in the file wins the 0,1,0 tie)
     keeps the site's own navy plate wherever a bg-brand utility lands. The arbitrary
     hover/active values are the button's own, matched verbatim so the press states
     survive the restatement. */
  .bg-brand-400 {
    background-color: #0d142a !important;
  }
  .bg-brand-300 {
    background-color: #204794 !important;
  }
  [class*="hover:bg-[#252C3F]"]:hover {
    background-color: #252c3f !important;
  }
  [class*="active:bg-[#0C1226]"]:active {
    background-color: #0c1226 !important;
  }
  /* `text-brand-dark` / `text-brand-400` resolve to #0d142a -- the design system's
     ink colour, not an accent. It currently only lands on <button>s (which take
     `button { color: inherit }`), but on any other element it would render at
     ~1.05:1 on our cards. Pin it light. */
  .text-brand-dark,
  .text-brand-400 {
    color: var(--wx-text) !important;
  }
  /* the design system's ACCENT is a third brand token, --color-brand-active (#1b4de4),
     and the mobile header's language/units control ("globe US | °F v") is the one place
     that paints with all three of its hooks at once: `text-brand-active` on the <button>,
     `border-l-brand-active` on the hairline before °F, `fill-brand-active` on the globe.
     Two of the three were flattened, so the control rendered half-blue, half-grey:
     - our own `button { color: inherit }` is UNLAYERED, and an unlayered normal
       declaration outranks a declaration inside Tailwind's utilities cascade layer no
       matter the specificity -- so the button, and the "US"/"°F" spans inheriting from
       it, took the
       page's body grey, while the globe and chevron <svg>s (not buttons) kept the blue.
     - the hairline took the blanket `* { border-color }` grey.
     Restore all three together with the theme's link blue -- #1b4de4 itself is only
     2.4:1 on the dark chrome. At >=768px the site swaps in neutral `md:` variants
     (`md:text-gray-900` / `md:border-l-gray-900`) whose class tokens are present in the
     list at EVERY width, so only the breakpoint can distinguish them: scope the accent to
     the widths where blue is what weather.com actually paints. */
  @media (max-width: 767px) {
    [class*="text-brand-active"] {
      color: var(--wx-link) !important;
    }
    [class*="border-l-brand-active"] {
      border-left-color: var(--wx-link) !important;
    }
    [class*="fill-brand-active"] {
      fill: var(--wx-link) !important;
    }
  }

  /* ---- restore the site's own `text-white` ------------------------------- */
  /* weather.com marks every piece of text that sits ON a saturated fill with
     the `text-white` utility. It ships un-!important inside Tailwind's utilities
     cascade layer, so our unlayered `p, li, ...`/`a` !important rules beat
     it and repainted ALL of it -- 22 nodes on a single Today page. The damage
     is worst where the fill carries the meaning:
     - the SEVERE-WEATHER ALERT banner (`bg-alert-severe` #ba0d00): the
       "Tornado Warning" line and its "Until ..." / "+6 More" text dropped to
       our body grey #c4cdd6 -> 4.2:1 on the red (an AA fail for the 14px line)
       and the whole banner read as muted chrome rather than an emergency.
     - the current-conditions hero (Feels Like / High / Low / Chance of Rain).
     - the brand CTAs ("Unlock 15 minute details" on #204794, "See Details",
       "Sign in") whose label took our LINK BLUE on a blue fill -> 3.7:1.
     Restore pure white -- it is what the site paints and it reads on every one
     of those fills. The alert / brand background colors are never touched. */
  .text-white {
    color: #ffffff !important;
  }
  /* `text-primary-foreground` is the same convention one token further in: the near-white
     label the design system puts on a SOLID CTA (the header Sign-in button and the Today
     "Next 10 Days" link are its only two users; nothing on the site paints `bg-primary`).
     It reached the page as link-blue anyway, because `button { color: inherit }` below is
     UNLAYERED and so outranks the utility inside Tailwind's cascade layer -- the button
     took the colour of the `<a>` wrapping it. Pin the white the site actually paints. */
  .text-primary-foreground {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* ...but the content hubs (/health, /pets, /home-garden) DO paint `bg-primary`:
     the selected category chip is `bg-primary text-primary-foreground`, natively a
     near-black pill with a near-white label. Our `--primary` remap makes that pill
     the light link blue, and the white pinned above lands on it at 2.38:1. Where
     the element carries the fill itself, give it the dark `--primary-foreground`
     the design system pairs with `--primary`; the two-class selector keeps the
     dark-filled CTAs (Sign in, Next 10 Days) on white. */
  .bg-primary.text-primary-foreground {
    color: var(--primary-foreground) !important;
    -webkit-text-fill-color: var(--primary-foreground) !important;
  }

  /* ---- data tables (hourly / 10-day details) ---------------------------- */
  table,
  thead,
  tbody,
  tfoot {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border) !important;
  }
  thead th,
  th {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text) !important;
    border-color: var(--wx-border) !important;
  }
  tbody tr:nth-child(even) {
    background-color: var(--wx-surface-2) !important;
  }
  td {
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border) !important;
  }
  tbody tr:hover {
    background-color: #232a33 !important;
  }
  /* accordion detail rows in the 10-day list */
  [data-testid="daily-forecast"] details,
  [data-testid="daily-forecast"] summary,
  details[data-testid],
  summary[data-testid] {
    background-color: transparent !important;
    color: var(--wx-text-2) !important;
  }
  /* each 10-day row is a <button> that paints a light #f2f2f2 fill in two states
     our static surface rules don't match: on :hover, and while EXPANDED
     (aria-expanded="true", the open accordion day). The row text is already
     lifted light, so the bright fill renders light-on-light and the day/temps
     wash out. Darken both states to an elevated dark surface so the light text
     stays legible (the colored temperature range bar is untouched). */
  [data-testid="daily-forecast"] button:hover,
  [data-testid="daily-forecast"] summary:hover,
  [data-testid="daily-forecast"] li:hover,
  [data-testid="daily-forecast"] button[aria-expanded="true"],
  [data-testid="daily-forecast"] [aria-expanded="true"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the expanded day-row's circular collapse toggle (the up-chevron disc) paints
     a light fill via Tailwind STATE-VARIANT utilities -- group-data-[state=open]:
     group-hover:bg-gray-200 and max-sm:group-data-[state=open]:bg-gray-100. Those
     compile to variant-prefixed class names (NOT the plain .bg-gray-100 selector
     our surface rule matches), and we never mapped bg-gray-200 at all -- so on
     hover the disc flashed a bright grey #cdcdcd circle on the dark card. Match
     the variant classes by substring + scope to the forecast so the toggle reads
     as a subtle elevated dark disc (the temperature range bar is untouched).
     The variant class sits in the class list in EVERY state while the site only
     PAINTS it on hover / while open, so these must be state-scoped: matched
     unconditionally they fill all ten rows and their chevron discs permanently,
     which both departs from the site's transparent rows and makes :hover a no-op
     (the row already carried the exact colour hover resolves to). */
  [data-testid="daily-forecast"] button:hover [class*="bg-gray-100"],
  [data-testid="daily-forecast"] button:hover [class*="bg-gray-200"],
  [data-testid="daily-forecast"] button:hover [class*="bg-neutral-100"],
  [data-testid="daily-forecast"] button:hover [class*="bg-neutral-200"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-gray-100"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-gray-200"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-neutral-100"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-neutral-200"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the Hourly page's Precipitation column draws each row's bar as a div whose
     EMPTY TRACK is an INLINE `background-color: rgb(245,245,245)` carrying no
     class at all -- so neither .bg-gray-100 nor any other utility rule reaches
     it, and the whole column renders as a stack of bright white pills down the
     dark table. It only exists once the Precipitation tab is opened, so a
     load-time scan never sees it. The FILLED portion of a rainy hour is a
     separate inline saturated blue and is data: only the #f5f5f5 track is
     remapped, to a subtle dark track the way it reads on the site's white card. */
  [style*="background-color: rgb(245, 245, 245)"] {
    background-color: var(--wx-border) !important;
  }
  /* the Hourly table's Cloud Cover tab draws each row's bar as an 8px pill with an
     INLINE `background-color: rgb(202, 217, 226)` and centres its `text-gray-900`
     percentage ON the pill (16px text on an 8px bar). The label is lifted to --wx-text by
     the text rules, so the pill has to be dark enough to carry white text while staying
     a visible cloud-grey against the card; the bar's WIDTH is the data and is untouched.
     The dotted rail beside it uses the same colour as a background-IMAGE, which this
     `background-color:` substring does not match -- its dots stay as shipped. */
  [style*="background-color: rgb(202, 217, 226)"] {
    background-color: #4f6a80 !important;
  }
  /* the Cold & Flu extended-forecast scrubber paints one segment per day from the
     flu-risk ramp as an INLINE background-color, same shape as the track above. The
     ramp's bottom step is achromatic #f2f2f2 -- invisible on the site's white card,
     which is the point ("nothing here") -- but on our dark card it is the brightest
     thing on the page and the ramp reads INVERTED: very low shouts, very high whispers.
     Sink the bottom step to the track tone so the ordering survives. Every chromatic
     step (#d9dcfd -> #17007e) is data and is untouched, and the legend swatch starts at
     #d9dcfd, so nothing in the legend disagrees with this. */
  [style*="background-color: rgb(242, 242, 242)"] {
    background-color: var(--wx-border) !important;
  }
  /* ---- forms / location search ----------------------------------------- */
  input,
  textarea,
  select {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
    border-color: var(--wx-border-2) !important;
  }
  input::placeholder,
  textarea::placeholder {
    color: var(--wx-text-muted) !important;
    opacity: 1 !important;
  }
  /* EXCEPT range sliders: weather.com renders the radar timeline scrubber and
     the Cold-&-Flu / Allergy "extended forecast" scrubber as a natively
     TRANSPARENT `input[type=range]` stacked on top of the real, styled track
     (a white pill + a coloured elapsed bar + a dark knob). The blanket `input`
     rule above filled that box with an opaque dark surface, so the slider
     covered its own track: both scrubbers rendered as a flat empty bar with no
     visible handle and no risk-level colour. Give the range input its
     transparency back; the track beneath paints normally.
     accent-color covers the opposite case: the rebuilt radar app's Map Menu
     ("Layer Transparency") leaves its slider entirely to the UA, tinted
     `accent-gray-900`. The UA paints the FILLED part in accent-color and the
     remainder in its own light track, so on a dark panel the filled part sinks
     out of sight while the empty part glares and the control reads as its own
     inverse -- and no element, pseudo or author declaration is involved, so
     nothing scans it. The UA ignores accent-color wherever the site styles the
     thumb itself, which is why the two scrubbers above keep their own colours. */
  input[type="range"] {
    background-color: transparent !important;
    border-color: transparent !important;
    accent-color: var(--wx-link) !important;
  }

  /* the location-search dialog + its results list must be opaque dark */
  [data-testid="header-search"],
  [data-testid="header-search"] [role="dialog"],
  [data-testid="location-search"],
  [role="listbox"],
  [data-testid="header-search"] ul,
  [data-testid="header-search"] li {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  /* the search field ships Tailwind's bg-white! utility, whose !important sits
     inside Tailwind's utilities cascade layer and so BEATS an unlayered override
     (layered important wins). bg-white! resolves var(--color-white), so we
     neutralise it by redefining --color-white ON the input itself -- variable
     resolution is layer-agnostic, so the rule still "wins" but computes our
     dark value. Pair with a legible muted placeholder (it ships text-gray-900). */
  [data-testid="header-search"] input,
  [data-testid="header-search"] input.bg-white,
  input[class*="bg-white"] {
    --color-white: #161d27 !important;
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="header-search"] input::placeholder,
  input[class*="bg-white"]::placeholder {
    color: var(--wx-text-muted) !important;
    opacity: 1 !important;
  }
  [data-testid="header-search"] li:hover,
  [data-testid="header-search"] a:hover,
  [role="option"]:hover,
  [role="option"][aria-selected="true"] {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="header-search"] a,
  [data-testid="header-search"] li,
  [role="option"] {
    color: var(--wx-text-2) !important;
  }
  /* the LEGACY header (radar / monthly / health pages) uses its own location
     search whose "Recents" flyout is a `RecentLocations--container` that ships a
     WHITE panel. It only appears on focus+type, so an audit scanning the closed
     header never sees it -- and the "Recents" title is already lifted light, so
     it renders light-on-white and nearly vanishes, while the "Favorite places"
     sign-up prompt (LocationsUpsell) draws a light-blue #cbdef0 CTA card. Darken
     the flyout panel + the upsell card, lift the near-black "Clear" button and
     the upsell copy so the whole dropdown reads on dark. Stable module-name
     prefixes (only the trailing build-hash rotates); the recent-location rows
     themselves already sit on the dark Listbox surface. */
  /* the white fill is set by a `[dir] .RecentLocations--container--<hash>` Helios
     rule at specificity (0,2,0) with !important, so a single-class override loses
     the cascade; raise ours above it with the combobox ancestor + the `--open`
     modifier compound (0,3,0). */
  [class*="SearchCombobox"] [class*="RecentLocations--container"][class*="RecentLocations--open"],
  [class*="RecentLocations--container"] {
    background-color: var(--wx-surface) !important;
  }
  [class*="RecentLocations--clearButton"] {
    color: var(--wx-link) !important;
  }
  [class*="LocationsUpsell--locationsUpsell"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="LocationsUpsell--locationsUpsell"] * {
    color: var(--wx-text-2) !important;
  }
  /* the recent-location ROWS sit on the dark Listbox surface, but each place
     NAME ("Koreatown", "New York City") ships a hardcoded near-black via its
     module class (styles--locationName) -- dark-on-dark and near-invisible on
     the flyout. It's set through `-webkit-text-fill-color` too, so pin BOTH.
     Scoped to the search flyout so the fragile styles-- prefix can't leak; the
     grey "state" subline (locationState) is already a legible muted token. */
  [class*="RecentLocations--container"] [class*="styles--locationName"],
  [class*="SearchCombobox"] [class*="styles--locationName"] {
    color: var(--wx-text) !important;
    -webkit-text-fill-color: var(--wx-text) !important;
  }
  /* every result row in that flyout carries two icons the audit can't see: a
     map-pin <svg> with NO fill attribute (so it paints the SVG default, pure
     black) and a "favorite" star drawn as a currentColor STROKE inheriting the
     module's near-black #252422. Both were invisible against the dark listbox.
     Lift them; a star that is actually favorited keeps its amber (#fdc107). */
  [class*="SearchedLocations--locationIcon"],
  [class*="SearchedLocations--locationIcon"] path {
    fill: var(--wx-text-2) !important;
  }
  [class*="FavoriteStar--icon"] {
    color: var(--wx-text-muted) !important;
  }
  [class*="FavoriteStar--isFavorite"] [class*="FavoriteStar--icon"] {
    color: #fdc107 !important;
    fill: #fdc107 !important;
  }

  /* ---- buttons ---------------------------------------------------------- */
  button {
    color: inherit;
  }
  /* the location pill / primary dark CTAs already read on dark; keep them
     consistent with the chrome and ensure a visible hover */
  [data-testid="location-picker-trigger"],
  [data-testid="header-menu-button"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="location-picker-trigger"]:hover,
  [data-testid="header-menu-button"]:hover {
    background-color: var(--wx-surface-2) !important;
  }

  /* ---- settings / units menu (must be opaque) --------------------------- */
  /* NOTE: no case-insensitive attribute flag (`[... i]`) anywhere in this file --
     the userstyles.org parser rejects it and drops the whole upload. The bare
     [role="menu"] below already covers every settings/units popover. */
  [data-settings-menu-trigger] + *,
  [role="menu"],
  [data-radix-popper-content-wrapper] > * {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [role="menuitem"]:hover {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  /* the LEGACY header (radar / monthly / allergy / health pages) opens its
     units + language/region picker from the "US °F" control as a full-width
     ExpandableMenu that ships a WHITE panel (ExpandableMenu--inner). Its unit
     tabs are already lifted light (so they read invisibly on the white panel)
     and its region list ships 170+ near-black rgb(37,36,34) ListItem names plus
     near-black expander/"Add" SVG icons -> the whole dropdown rendered as a
     bright sheet of dark-on-white / light-on-white text. Darken the panel and
     lift the near-black list text + icons; the active-unit tab keeps its light
     underline (handled by the TabList--tabSelected rule above). The stable
     module-name prefixes are matched by substring (only the build-hash rotates).
     This ExpandableMenu is the legacy component only -- the new SPA header's
     units popover is a Radix popper handled above, and its mobile nav drawer is
     dark already, neither of which carries ExpandableMenu--inner. */
  [class*="ExpandableMenu--inner"] {
    background-color: var(--wx-surface) !important;
  }
  /* the panel is a neutral units/region/language picker with no semantic colours,
     so lift ALL of its text + icons to readable body light: the region-section
     headers (Disclosure--SummaryDefault) and expander "+" icons ship near-black
     rgb(43,43,43), the country ListItem rows ship rgb(37,36,34), all dark-on-dark
     once the panel is darkened. The active-unit tab is marked by its light
     underline (TabList--tabSelected), not colour, so a blanket lift keeps it. */
  [class*="ExpandableMenu--inner"] * {
    color: var(--wx-text-2) !important;
  }
  [class*="ExpandableMenu--inner"] svg,
  [class*="ExpandableMenu--inner"] svg * {
    fill: var(--wx-text-2) !important;
  }

  /* the legacy Helios Popover (the AQI / UV "Levels" legend behind the module
     footers' Info button, and its siblings) is a white panel that only exists
     as `visibility: hidden` until clicked, and its pointer notch is a rotated
     square painted by the arrow's ::before. Both need the dark surface; the
     legend's colour swatches are inline fills and stay as the site paints. */
  [class*="Popover--popover"],
  [class*="Popover--popover"] [data-popper-arrow]::before {
    background-color: var(--wx-surface-2) !important;
  }

  /* ---- footer ----------------------------------------------------------- */
  footer,
  [data-testid="footer"],
  [data-component="footer"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text-2) !important;
  }
  /* ...but `header` / `footer` are BARE TAG selectors, and the SPA also uses those
     tags for a card's own title row and its source/attribution strip (the AQI
     card's "All Pollutants" heading and its "Air Quality Index" credit line).
     Those are transparent on the site; taking the page-chrome fill painted a
     near-black band straight across the middle of an elevated card. The page's
     real header/footer are direct children of <main>, never inside a <section>,
     so scoping the reset to section descendants can't reach them. */
  section header,
  section footer {
    background-color: transparent !important;
  }
  footer a,
  [data-testid="footer"] a {
    color: var(--wx-text-2) !important;
  }
  footer a:hover {
    color: var(--wx-link-hover) !important;
  }
  /* the footer's nav links are neutral by design, but the ForecastWatch accuracy
     citation is an INLINE link inside a sentence, blue (#1b4de4 legacy / text-blue-500
     in the SPA) on both frontends -- `footer a` flattened it to body grey, so it read
     as plain prose. Give the in-paragraph links their accent back; the link ROWS above
     stay neutral. */
  footer p a,
  [class*="Footer--container"] p a {
    color: var(--wx-link) !important;
  }
  /* the footer's sibling-brand lockup is four <img> tiles. Two of them are
     transparent-background artwork drawn for the site's WHITE page: The Weather
     Company is a #00279E navy wordmark (~1.7:1 on our chrome) and Weather
     Underground bakes its "WEATHER UNDERGROUND" tagline in as #1C1F22. Nothing
     in CSS reaches inside an <img>, and no bucket sees it (it is a raster/vector
     FILE, not a colour). Put the white page back BEHIND them -- same trick as the
     header wordmark above -- so the brand colours stay exact. The Weather Channel
     tile ships its own blue plate and Storm Radar its own dark rounded square, so
     both are left alone (a plate would show through the latter's cut corners).
     One src match covers both frontends: the SPA serves
     `/_next/static/media/the-weather-company.<hash>.svg`, legacy Daybreak
     `/monthly/assets/the-weather-company.resource.<hash>.svg`. */
  img[src*="the-weather-company"],
  img[src*="weather-underground"] {
    background-color: #ffffff !important;
    border-radius: 4px !important;
  }

  /* ---- Taboola "More from weather.com" recommendation strip ------------- */
  /* The Taboola widget (trc_*) renders white cards with hardcoded near-black
     titles; our surface darkening leaves the titles dark-on-dark. Darken its
     surfaces and lift the title/branding text. (Its thumbnail imagery stays.) */
  .trc_rbox,
  .trc_rbox_outer,
  .trc_rbox_div,
  .trc_excludable,
  .trc_spotlight_item,
  .trc_related_container,
  .trc_popover,
  .trc_exclude_overlay {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  .video-title,
  .trc_el .video-title,
  .video-label,
  .trc_el,
  .syndicatedItem,
  .trc_rbox .branding,
  .trc_rbox_header_span {
    color: var(--wx-text-2) !important;
  }
  /* the widget FOOTER carries the ad disclosure ("Sponsored Links by Taboola",
     "Promoted Links"). Its spans are pure black and sit outside every `.trc_*`
     surface class above, so the disclosure vanishes on the darkened card. */
  .trc-widget-footer,
  .trc-widget-footer span,
  .trc-widget-header,
  .trc-widget-header span {
    color: var(--wx-text-muted) !important;
  }
  /* Taboola now ships a "brand kit": it writes its palette as INLINE custom properties on
     <html> (`--brand-color-text-primary: #252422`, `--brand-color-bg-base: #FFFFFF`) and
     its own late-injected rules read them at (0,4,0) --
     `.tbl-feed-card:not([class*="rec-reel"]) .videoCube .video-title { color:
     var(--brand-color-text-primary) !important }` -- which out-specifies the single-class
     rule above, so EVERY card title in the feed computed #252422 on our card (1.04:1) and
     the whole "Sponsored Content" block rendered as thumbnails with no captions. Only the
     first card escapes, because its title overlays the image and is white. Redefining the
     token on the widget root is specificity-agnostic and reaches every consumer at once
     (an !important author declaration also beats the NORMAL inline one on <html>).
     The advertiser name is a separate `.brand-name` at #0a0a0a that no token feeds, and
     it renders through `-webkit-text-fill-color`, so pin both properties. The cream "AD"
     disclosure badge is left exactly as the site paints it. */
  .trc_rbox,
  [id*="taboola"] {
    --brand-color-text-primary: var(--wx-text-2) !important;
  }
  .tbl-brand-kit-branding-row .brand-name {
    color: var(--wx-text-muted) !important;
    -webkit-text-fill-color: var(--wx-text-muted) !important;
  }
  /* the "hide this ad" overlay's Undo affordance is a <div>, not an <a>, so the link rules
     never reached it and it kept Taboola's #3366cc at 3.02:1 on the darkened card. */
  .trc_exclude_undo_btn {
    color: var(--wx-link) !important;
  }
  /* hovering a feed card is the widget's only affordance: Taboola's per-placement rule
     (`.thumbs-feed-01-* .videoCube:hover .video-label-box .video-title`, 0,4,0, no
     !important) turns the title brand blue, and the `.video-title` !important lift above
     pins it. One class deeper than the brand-kit rule that repaints the titles at rest. */
  .trc_rbox .videoCube:hover .video-label-box .video-title.video-label {
    color: var(--wx-link-hover) !important;
  }
  /* Taboola's popover points at its trigger with a CSS-triangle: a 0/11/11/11
     border box whose left/right/top edges are transparent. The blanket
     `* { border-color }` painted all four, so the caret renders as a solid
     rectangle once the popover opens. Restore the triangle, pointing up into
     the darkened popover. */
  .trc_popover_arrow {
    border-color: transparent !important;
    border-bottom-color: var(--wx-surface) !important;
  }
  /* ...but the caret the eye actually sees is the arrow's `::after` -- a second, 10px
     triangle stacked on top of the 11px shadow one above, whose border-bottom-color is
     #fff. `*` does not match pseudo-elements and neither does the rule above, so the
     popover still pointed at its card with a white spike. Only one of top/bottom ever
     has a non-zero width (the `trc_bottom` / `trc_top` variants zero the other), so
     pinning both covers either direction without filling the box.
     The popover's remaining chrome is light too: `trc_popover_title_wrapper` ships a
     #f7f7f7 bar with a #ebebeb rule, and Taboola sets `color: #000` on
     `popupContentWrapper` / `trc_popover_content_wrapper`, which are matched CHILDREN --
     a matched rule beats the colour inherited from the popover, so the body copy stayed
     black on our dark panel. The whole widget is `visibility: hidden` until a
     recommendation card is hovered, so no load-time scan sees any of it. */
  .trc_popover_arrow::after {
    border-top-color: var(--wx-surface) !important;
    border-bottom-color: var(--wx-surface) !important;
  }
  .trc_popover_title_wrapper {
    background-color: var(--wx-surface-2) !important;
    border-bottom-color: var(--wx-border) !important;
  }
  .trc_popover_title_wrapper,
  .trc_popover_title,
  .popupContentWrapper,
  .trc_popover_content_wrapper,
  .trc_popover_content {
    color: var(--wx-text) !important;
  }
  /* Taboola paints a LOADING SKELETON before the feed arrives: `tbl-placeholder-card` is
     a 125px #f6f7f9 slab, its `::before` tiles a light shimmer GIF over the same #f6f7f9,
     and each `tbl-masker` is a #fff box that masks the slab down to the row shape THROUGH
     ITS BORDER (`border-left: 24px solid #fff`). The spinner is display:none once the feed
     loads, so a scan of a settled page reports clean -- but a stack of near-white cards
     flashes below the content on every page load, and our blanket `* { border-color }` had
     already turned the masker's white border grey, drawing a bar across each white slab.
     Take the slab, the shimmer image and the masker's fill AND border in one pass: a
     masker whose fill and border disagree is exactly the seam the border reset produced. */
  .tbl-placeholder-card {
    background-color: var(--wx-surface-2) !important;
  }
  .tbl-placeholder-card::before {
    background-color: var(--wx-surface-2) !important;
    background-image: none !important;
  }
  .tbl-masker {
    background-color: var(--wx-surface-2) !important;
    border-color: var(--wx-surface-2) !important;
  }
  /* the same feed's video-ad and story-widget card variants (thumbs-feed-01-*,
     above-the-feed-premium-*, banner-on-product-*) ship four more light surfaces that
     only exist once a card starts playing or renders its reel, so they never appear in a
     settled DOM: `tbl-editorial-video-container` is a full-cover #fff panel parked at
     opacity:0 and faded IN while the ad plays; `tbl-vignette-background-screen` is a #fff
     scrim at .8; and the two `tbl-text-under-*-background` plates are #ebebeb backings
     behind the title/branding lines -- which our `.video-title` / `.trc_el` rules already
     lift to light, so they land light-on-light. `tbl-ui-line` is the #333 divider drawn ON
     those plates, so it has to be lifted in the same pass or it vanishes into its new dark
     backing. The white `.video-cta-button` pill is deliberately left alone: it sits over
     the video thumbnail, not over our card, and Taboola pins `color: black !important` on
     its label, so it still reads. */
  [class*="tbl-editorial-video-container"] {
    background-color: var(--wx-surface) !important;
  }
  [class*="tbl-vignette-background-screen"] {
    background-color: var(--wx-base) !important;
  }
  [class*="tbl-text-under-title-background"],
  [class*="tbl-text-under-branding-background"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="tbl-ui-line"] {
    background-color: var(--wx-border-2) !important;
  }

  /* ---- Outbrain recommendation strips (international news lists) --------- */
  /* `#outbrain_widget_N` slots ship a white fill of their own and stay in flow at
     645x32 even when the widget mounts EMPTY (the inner `.ob-widget` never fills in
     regions where no campaign is served) -- two bare white pills under the article
     list. Sink the slot into whatever card it sits in; a populated strip's copy takes
     the body ink. */
  [id^="outbrain_widget"] {
    background-color: transparent !important;
  }
  .ob-widget,
  .ob-widget a {
    color: var(--wx-text-2) !important;
  }

  /* ---- interactive radar map: the rebuilt Tailwind map UI ---------------- */
  /* The /radar route now ships the SPA map app (floating layer pills over the basemap,
     a Map Menu sheet, a bottom timeline card) instead of the Helios ControlPanel handled
     further below. It writes its own palette as Tailwind ARBITRARY hexes, which no named
     `bg-*` utility rule reaches, and the ACTIVE state is exactly one of them:
     `bg-[#252422] text-white border-[#c5c4c9]` on the current layer pill (and on the Map
     Menu toggle while open) against `bg-white` siblings. #252422 is within 1.05:1 of our
     card, so the pill the site inverts to near-black read identically to the unselected
     ones our .bg-white rule darkens -- the strip showed no current layer at all. Invert
     it the other way, as the chart tab strip and the units radiogroup are: a light plate
     with chrome ink. The pill's glyph carries `text-white`, which is a matched rule, so
     it has to be re-pointed with the label.
     Two other elements ship the same hex and must NOT flip: the overlay/theme check badge
     and the thumbnail carousel arrows both sit ON a light map thumbnail, where the site's
     near-black is correct. `border-[#c5c4c9]` is carried only by the active pills, so it
     is what separates them. */
  [class*="bg-[#252422]"][class*="border-[#c5c4c9]"] {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  [class*="bg-[#252422]"][class*="border-[#c5c4c9]"] svg {
    color: var(--wx-chrome) !important;
  }
  /* the Map Menu's own Map Type list marks its selected row with the same hex; every row
     in that list carries `border-[#f2f2f2]`, so the pair picks out the selected one. It
     sits INSIDE the darkened sheet rather than over the map, so it takes an elevated row
     fill rather than the full inversion. */
  [class*="bg-[#252422]"][class*="border-[#f2f2f2]"] {
    background-color: var(--wx-border-2) !important;
  }
  /* the timeline scrubber is three unnamed arbitrary values: a `bg-[#e8e8e8]` groove, a
     `bg-[#b1b1b0]` elapsed fill inside it, and a dashed `border-gray-900` NOW marker the
     blanket border reset flattens to the subtle line colour. On the site's white card the
     groove is invisible and the marker is near-black; on the dark card that inverts --
     the groove became the brightest thing in the panel and the marker vanished. Keep the
     past/future ordering (past stays the more prominent of the two) with the groove on
     the component border and the elapsed fill on the muted ink. */
  [class*="bg-[#e8e8e8]"] {
    background-color: var(--wx-border-2) !important;
  }
  [class*="bg-[#b1b1b0]"] {
    background-color: var(--wx-text-muted) !important;
  }
  [class*="border-dashed"][class*="border-gray-900"] {
    border-color: var(--wx-text-muted) !important;
  }

  /* ---- interactive radar map: floating control / insight panels --------- */
  /* The radar map's two floating cards -- the location/alert "insight" card
     (place name + severe-weather alert + "See all N alerts") and the bottom
     timeline/layers control panel (time slider + Radar/Clouds/Temperatures/
     All Layers + Hide menu) -- are the map's own UI, NOT the basemap. They ship
     white via HASHED CSS-module classes that have no data-testid/role to hook,
     so we target the STABLE module-name PREFIX (`ControlPanel--controlContainer`,
     `ControlPanel--noticeContainer`, `InsightPanel--npContainer`, ...); only the
     trailing build-hash (`--SueT4`) rotates, the prefix is stable. ROT RISK: if
     IBM changes the CSS-modules localIdentName format these stop matching --
     acceptable, since no stable hook exists and leaving them bright-white over
     the dark map is worse. We darken the surfaces + lift their text, while the
     blue links ("See all alerts"), the colored layer-thumbnail images and the
     orange alert icon keep their own colors (links/imgs handled elsewhere; we
     don't recolor a/button/img here). The basemap + colored radar overlay are
     left untouched by the imagery rules just below. */
  [class*="ControlPanel--controlContainer"],
  [class*="ControlPanel--noticeContainer"],
  [class*="InsightPanel--npContainer"],
  [class*="InsightPanel--insight"],
  [class*="LayerDetail--layerDetailContainer"],
  section.card[class*="Wrapper--radarWrapper"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  [class*="InsightPanel--"]:not(a):not(button),
  [class*="ControlPanel--controlContainer"] *:not(a):not(button):not(img):not(svg):not(canvas),
  [class*="LayerDetail--"]:not(a):not(button) {
    color: var(--wx-text) !important;
  }
  /* ...but the InsightPanel :not(a):not(button) rule above (specificity 0,1,2 thanks to
     its two :not()s) also swallowed the insight card's two SEMANTIC accents: the
     alert warning icon is an <svg> that inherits currentColor from the amber
     `InsightPanel--alertIcon` (#ffb900), and the "Read details" CTA is a <span>
     (InsightPanel--alertsLink) coloured brand blue -- so the alert lost its amber
     warning tint (rendered a neutral white circle-i) and the link lost its blue
     affordance (plain white, inconsistent with the blue "...Alert until..." line right
     above it). Restore both, scoped under npContainer (0,2,0) to out-rank the broad
     rule; amber reads on the dark card, blue is the theme link. */
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertIcon"] {
    color: #ffb900 !important;
  }
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertsLink"] {
    color: var(--wx-link) !important;
  }
  /* ...that link's own chevron is an `<svg class="InsightPanel--arrow...">`, which the
     same broad rule matches DIRECTLY -- and a matched rule beats a colour inherited from
     the link -- so "Read details" read blue while its arrow stayed plain light. The
     wrapping `<span class="Icon--iconWrapper">` carries no InsightPanel class and so
     inherits correctly; only the svg needs re-pointing (its <path> is currentColor). */
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertsLink"] [class*="InsightPanel--arrow"] {
    color: var(--wx-link) !important;
  }
  /* the premium map layers ("24-Hour Future Radar", ...) label their unlock CTA with
     `LayerDetail--goPremium` in the brand navy #204794 -- 2.0:1 on the dark panel, so it
     cannot stay -- and the broad ControlPanel/LayerDetail text rule flattened it to plain
     light, which left the only sign-in affordance in the layer list reading as body copy.
     Give it the link accent instead of the generic lift -- via its `textBlock` parent,
     because that broad rule carries two `:not()`s and so sits at (0,1,2): a single-class
     override loses the tie and never paints. */
  [class*="LayerDetail--textBlock"] [class*="LayerDetail--goPremium"] {
    color: var(--wx-link) !important;
  }

  /* The radar map's CONTAINER card now ships its white fill via a higher-specificity
     doubled-class Helios rule ([dir] .Wrapper--radarWrapper--<hash>.Wrapper--radarWrapper--<hash>
     { background-color: var(--backgroundPage) !important }) that out-specifies the
     section.card[class*="Wrapper--radarWrapper"] rule above -- so the radar legend
     strip at the top of the map rendered bright white again. Redefine the Helios
     surface tokens ON the wrapper itself: variable resolution is specificity-agnostic,
     so their rule still wins the cascade but COMPUTES our dark value (the basemap
     tiles are <img>/<canvas> and stay untouched). */
  [class*="Wrapper--radarWrapper"] {
    --backgroundPage: var(--wx-surface) !important;
    --backgroundCard: var(--wx-surface) !important;
  }
  /* the radar timeline's tick labels (Now / 7a / 8a / ...) are <button> nodes
     (TimeLine--tickLabelButton) that the ControlPanel :not(button) rule above
     excludes; "Now" ships a near-black #2b2b2b that goes dark-on-dark. Lift the
     ticks to a readable light and the current "Now" label to primary. */
  [class*="TimeLine--tickLabelButton"] {
    color: var(--wx-text-2) !important;
  }
  [class*="TimeLine--nowContainer"] [class*="TimeLine--tickLabelButton"] {
    color: var(--wx-text) !important;
  }
  /* the radar map's +/- zoom control is a single WHITE pill split by a 1px #cecece
     hairline -- a light-on-light divider inside a region the theme deliberately leaves
     the site's own, since it sits on the basemap. The blanket `* { border-color }` reset
     crosses straight into it and repaints that hairline --wx-border, so the white pill
     renders with a hard black bar across its middle. Nothing else about the control is a
     colour we touch, so neither scanner reports it; only a native-vs-themed border diff
     over the map does. Put the site's own hairline back. The `Radar--zoomContainer`
     module prefix is stable (only the trailing build-hash rotates). */
  [class*="Radar--zoomContainer"] button {
    border-color: rgb(206, 206, 208) !important;
  }

  /* the map's SELECTED layer (Radar / Clouds / Temperatures) is marked ONLY by
     brand blue: a 2px ring on its thumbnail and a blue label. The blanket
     `* { border-color }` rule flattened the ring and the ControlPanel text rule
     above (specificity 0,1,5 thanks to its five :not()s) repainted the label
     primary-light -- so every layer looked identical and nothing showed which
     one was on. Re-mark the selection with the theme's link blue (the site's
     own #1b4de4 only reaches 2.4:1 on our dark panel). Two classes deep to
     out-rank the ControlPanel rule. */
  [class*="LayerDetail--layerDetailContainer"] [class*="LayerDetail--selectedLayerTypeTitle"] {
    color: var(--wx-link) !important;
  }
  /* the selected layer's thumbnail ring: the expanded list marks it with the blue
     `layerDetailImage` border, but the COLLAPSED control-panel round thumbnails
     (Radar / Clouds / Temperatures) mark it with a blue border on a newer
     `layersIconContainer` element the blanket `* { border-color }` flattens to grey
     -- so the round thumbnail lost its selection ring. Restore both, scoped under
     the `selectedLayerType` ancestor so only the active layer is ringed. */
  [class*="LayerDetail--selectedLayerType"] [class*="LayerDetail--layerDetailImage"],
  [class*="LayerDetail--selectedLayerType"] [class*="LayerDetail--layersIconContainer"] {
    border-color: var(--wx-link) !important;
  }
  /* the layer thumbnails sit on an #e8e8e8 placeholder that shows through until
     each preview image loads (and on every re-render of the All Layers list) --
     a grid of bright squares on the dark panel. */
  [class*="LayerDetail--thumbnailPlaceholder"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the legacy Toggle (Map Options -> "Radar Timeline Autoplay", and every
     per-layer LayerOption switch) encodes its state ONLY in the track fill, with
     identical class names in both states: OFF is a light #b1b1b0, ON is a
     near-black #252422 -- both read fine on the site's white panel, but on our
     dark panel the ON fill sinks into the surface while the OFF fill glares, so
     the control reads exactly BACKWARDS. The white knob's checkmark inherits our
     lifted light text and disappears into the knob on top of that. Repaint ON
     with the theme accent, give OFF a visible-but-quiet track, and put the
     checkmark back to a dark glyph on the white knob.
     `:checked` lives on a visually-hidden input that PRECEDES the track label, so
     match forward with adjacent siblings (CSS2 only -- no `~`); the label text is
     optional, hence both forms. */
  [class*="Toggle--track"] [class*="Toggle--switchWrap"] {
    background-color: var(--wx-border-2) !important;
  }
  [class*="Toggle--checkbox"]:checked + [class*="Toggle--track"] [class*="Toggle--switchWrap"],
  [class*="Toggle--checkbox"]:checked + [class*="Toggle--labelText"] + [class*="Toggle--track"] [class*="Toggle--switchWrap"] {
    background-color: var(--wx-link) !important;
  }
  [class*="Toggle--switch"] svg,
  [class*="Toggle--switch"] svg path {
    color: var(--wx-chrome) !important;
    fill: var(--wx-chrome) !important;
  }

  /* the Map Options tabs ("Layers and Styles" / "Specialty Maps") mark the
     active tab with a 2px black border-bottom; the `*` rule painted it the
     subtle border grey (1.15:1) and the active tab lost its underline. */
  [class*="TabList--tabSelected"] {
    border-bottom-color: var(--wx-text) !important;
  }
  /* ...and every tab LABEL in that component ships the Helios ink #252422, so
     the category strips on the legacy content hubs (/safety, /storms/*) go
     dark-on-dark. The site marks the current tab only by the underline above,
     never by colour, so one uniform lift keeps the distinction intact. */
  [class*="TabList--tab"] {
    color: var(--wx-text-2) !important;
  }
  /* Map Options radio groups (Map Style, Main map layer, radar speed): the
     visual control IS the appearance:none <input>, and its selected dot is an
     `::after` filled with the Helios ink #252422. On the site's white ring that
     dot is the ONLY per-row selected marker; our darkened ring left it
     near-black on near-black, so checked and unchecked rows rendered identically.
     Element-bg and chroma scans both pass -- a pseudo-element on a 20px control,
     achromatic either way. */
  [class*="Radio--inputClass"]:checked::after {
    background-color: var(--wx-text) !important;
  }
  /* with the range input transparent again, the radar scrubber's real track is
     visible -- and it is `background: var(--PureWhite)`, a bright 264x14 pill on
     the dark panel. Remap the Helios token ON the track (variable resolution is
     specificity-agnostic) and lift the near-black #252422 slider handle so it
     still reads on the darkened track. The grey elapsed fill (--Koala30) and the
     Cold-&-Flu scrubber's PURPLE risk bar are data and stay untouched -- which is
     why the handle rule is scoped to the radar ControlPanel and not to every
     range input on the site. */
  [class*="ControlPanel--controlContainer"] [class*="TimeLine--historyContainer"] {
    --PureWhite: var(--wx-surface-2);
  }
  /* Chromium and Gecko thumb pseudo-elements must be SEPARATE rules -- a mixed
     vendor selector list is invalid in both engines and drops the whole rule. */
  [class*="ControlPanel--controlContainer"] input[type="range"]::-webkit-slider-thumb {
    background-color: var(--wx-text) !important;
  }
  [class*="ControlPanel--controlContainer"] input[type="range"]::-moz-range-thumb {
    background-color: var(--wx-text) !important;
  }

  /* ---- Cold & Flu "Extended Flu Forecast" timeline control ---------------- */
  /* Below the flu-risk choropleth map sits a timeline control that ships a #fafafa
     fill (ExtendedFluForecast--controlContainer) -- a bright white strip on the dark
     card. Darken it; its date ticks are HTML spans (FluRiskTimeLine--tickLabel) and
     its play icon is a path[fill="#2B2B2B"], both of which go dark-on-dark once the
     strip is darkened, so lift them. The flu-risk MAP above and the colored severity
     dot are data and stay untouched. */
  [class*="ExtendedFluForecast--controlContainer"],
  [class*="ExtendedAllergyForecast--controlContainer"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [class*="FluRiskTimeLine--tickLabel"] {
    color: var(--wx-text-2) !important;
  }
  [class*="ExtendedFluForecast--controlContainer"] svg path[fill="#2B2B2B"],
  [class*="ExtendedFluForecast--controlContainer"] svg path[fill="#2b2b2b"] {
    fill: var(--wx-text-2) !important;
  }
  /* the "New York CDC Flu Report" bar chart on the same page is a D3 SVG whose
     High/Med/Low gridlines and y-axis ticks are `<line stroke="currentColor">` inside
     `g.grid`/`g.axis--y` -> `g.tick`, resolved to #ececec. At 1px on the site's white
     card that lattice is all but invisible; on our dark card it is the brightest thing
     in the widget and out-shouts the blue case bars. The colour never appears as an
     attribute value (it comes from a rule we cannot read), so the `svg line[stroke=...]`
     attribute selectors at the bottom of this file can't reach it. Match the ticks by
     their chart's stable module prefix and drop them to the component border, which is
     as subtle against dark as #ececec was against white. Only chrome lives in `g.tick`
     -- the case bars are separate <rect>s and keep their data blue. */
  [class*="FluCDCReport--chart"] g.tick line {
    stroke: var(--wx-border-2) !important;
  }

  /* the "Very Low ... Very High" legend floats over the choropleth map in a
     WHITE box; it inherits the card's lifted light text from our Card--card
     rule, so its two labels rendered light-on-white (~1.7:1) and vanished.
     Darken the box (like the map's own "Now" chip) so the lifted labels read;
     the purple risk gradient swatch inside keeps its data colors. */
  [class*="ExtendedFluForecast--legendBox"],
  [class*="ExtendedAllergyForecast--legendBox"] {
    background-color: var(--wx-surface) !important;
  }

  /* ---- 15-day allergy forecast SVG area chart ---------------------------- */
  /* The allergy forecast is an SVG area chart whose plot area is filled white via a
     path[fill="#FFFFFF"] plus a #ffffff -> light-purple area gradient -- neither of
     which a DOM-background audit can see, so it renders a stark white block on the
     dark card. Darken the fill and remap the gradient stops so the area blends into
     the card; the blue forecast LINE (stroke #0062FF) and its dots are data and
     stay verbatim. */
  [data-testid="AllergyForecastChart"] path[fill="#FFFFFF"],
  [data-testid="AllergyForecastChart"] path[fill="#ffffff"],
  [class*="AllergyLineChart"] path[fill="#FFFFFF"],
  [class*="AllergyLineChart"] path[fill="#ffffff"] {
    fill: var(--wx-surface-2) !important;
  }
  [data-testid="AllergyForecastChart"] stop,
  [class*="AllergyLineChart"] stop {
    stop-color: var(--wx-surface-2) !important;
    stop-opacity: 1 !important;
  }

  /* EVERY shadcn popover draws its pointer notch as two stacked
     `<svg class="fill-white">` polygons (a shadow layer under a fill layer)
     rather than a bordered CSS triangle, so the blanket border reset never
     touches it and the popover body's own dark fill never reaches it: a bright
     white arrowhead hung off the edge of an otherwise dark panel. Both the
     article Share popover and the AQI / UV "Levels" legend behind each module's
     info button use it. The notch must match the popover surface, so scope it to
     `[data-slot="popover-content"]` (the design-system's own wrapper, which every
     one of them carries) -- a global `fill-white` remap would blacken the
     play/overlay glyphs the site paints white on top of photo thumbnails. */
  [data-slot="popover-content"] svg[class*="fill-white"],
  [data-slot="popover-content"] svg[class*="fill-white"] polygon,
  [data-slot="popover-content"] svg[class*="fill-white"] path {
    fill: var(--wx-surface) !important;
  }

  /* syndicated articles credit the partner with `<img class="partner-logo">`
     under "In partnership with" -- e.g. the SURFER wordmark, black linework on a
     transparent PNG, correct on the site's white page and invisible on our card.
     No selector reaches inside an <img> and no bucket sees it (it is artwork, not
     a colour), and it only exists on partner articles, so page-type sampling
     misses it too. Invert to flip the ink light; the hue-rotate returns any
     coloured partner mark (Healthline, Outside) to roughly its own hue, and the
     transparent background stays transparent because filters leave alpha alone. */
  img.partner-logo {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* The "DeeperDive" AI-overview widget injected into news articles (#dd-widget)
     ships its own light-theme chrome: a white footer input pill, a navy brand
     logo, dark #2f3c4c title/summary copy, and a left-to-right white scroll-fade
     shader behind the "Full Summary" button. All of it lands on our dark article
     card -- the copy reads dark-on-dark and the pill + fade flash bright. Re-skin
     the widget surfaces dark and lift its text; the blue send button keeps its
     identity. Stable third-party class names (not hashed). */
  #dd-widget .dd-widget-title-text,
  #dd-widget .dd-widget-title-text span,
  #dd-widget .dd-widget-article-summary-content-wrapper,
  #dd-widget .dd-widget-article-summary-button {
    color: var(--wx-text) !important;
  }
  /* the shader sits under the absolutely-positioned "Full Summary" button and must be
     OPAQUE for the button's full width, or the clamped paragraph shows through the label;
     the widget publishes that width as `--dd-article-summary-button-width` (150px when
     unset) and ends its own gradient there, so this one ends at the same stop. */
  #dd-widget .dd-widget-article-summary-button-shader {
    background-image: linear-gradient(to right, rgba(28, 33, 40, 0), var(--wx-surface) calc(100% - var(--dd-article-summary-button-width, 150px))) !important;
  }
  #dd-widget .dd-widget-input-wrapper {
    background-color: var(--wx-surface-2) !important;
    border: 1px solid var(--wx-border) !important;
  }
  #dd-widget .dd-widget-branding-logo svg path {
    fill: var(--wx-text) !important;
  }
  /* The widget added a redesigned "compact" suggested-question list
     (.dd-widget-questions -> .dd-widget-question-container rows). The FIRST /
     highlighted row (and the :hover state of every row) ships a near-white fill
     authored in modern color(srgb 0.96 0.96 0.96) NOTATION -- which a bg-color
     audit reading rgb() can't pattern-match, so it scanned clean while rendering
     a bright pill. Our text rules already lift the question copy to light, so it
     landed light-on-light and the first suggestion was nearly invisible. Darken
     every question row + its hover to the elevated dark surface so the light text
     reads; the blue send button keeps its identity. */
  #dd-widget .dd-widget-question-container,
  #dd-widget .dd-widget-question-container:hover {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }

  /* ---- OpenWeb (Spot.IM) reactions + comments on news/video articles ------ */
  /* Every article ends with OpenWeb's widgets ("How Do You Feel About This Video?"
     reactions, then the comment thread). They render inside an OPEN SHADOW ROOT on a
     custom element whose tag name is a per-publisher hash (<ow-u87ksa0ilag>), so no
     rule of ours reaches inside and every DOM scan of the light DOM reports clean --
     while the widget paints a full-width WHITE slab across the bottom of the article
     plus a white notification bell.
     It is themeable after all: the shadow root declares its whole palette as
     `--spotim-*` custom properties on `:host`, and a rule in the OUTER tree that
     matches the host beats a `:host` rule, so the variables we set here resolve
     INSIDE the shadow tree. Match the host through its stable wrapper attributes
     (`data-spotim-app` / `data-spotim-module`) rather than the hashed tag name.
     `--spotim-color-scheme-l6` is the foreground base that l1..l5 derive their
     translucent tints from -- flipping it to light is what makes the derived borders
     and muted text work on dark. The brand blue (#0968ba, white text on it) already
     reads on dark and is left alone, as are the reaction emoji. */
  [data-spotim-app] > *,
  [data-spotim-module] > * {
    --spotim-page-background-color: #1c2128 !important;
    --spotim-card-background-color: #1c2128 !important;
    --spotim-surface: #161d27 !important;
    --spotim-conversation-background-color: transparent !important;
    --spotim-input-background-color: #161d27 !important;
    --spotim-sayctrl-background-color: #161d27 !important;
    --spotim-sticky-say-control-background-color: #1c2128 !important;
    --spotim-list-item-background: #161d27 !important;
    --spotim-list-item-foreground: #2d333b !important;
    --spotim-overlay-background-color: #1c2128 !important;
    --spotim-extract-background-color: #161d27 !important;
    --spotim-embedded-comment-background-color: #161d27 !important;
    --spotim-embedded-comment-preview-background-color: #161d27 !important;
    --spotim-message-hover-menu-background-color: #161d27 !important;
    --spotim-color-scheme-g1: #1c2128 !important;
    --spotim-color-scheme-g2: #e6edf3 !important;
    --spotim-color-scheme-l6: #e6edf3 !important;
    --spotim-color-scheme-l6-rgb: 230, 237, 243 !important;
    --spotim-color-scheme-l100: #14181d !important;
    --spotim-text-color-default: #e6edf3 !important;
    --spotim-message-text-color: #c4cdd6 !important;
    --spotim-text-color-muted: #8b949e !important;
    --spotim-text-color-x-muted: #8b949e !important;
    --spotim-text-color-xx-muted: #8b949e !important;
    --spotim-text-color-product-header: #e6edf3 !important;
    --spotim-reactions-title-color: #e6edf3 !important;
    --spotim-reactions-reaction-text-color: #8b949e !important;
    --spotim-pitc-header-color: #e6edf3 !important;
    --spotim-pitc-top-comment-color: #e6edf3 !important;
    --spotim-user-image-font-color: #c4cdd6 !important;
    --spotim-ads-text-color: #8b949e !important;
    --spotim-ads-footer-color: #8b949e !important;
    --spotim-share_icon_color: #c4cdd6 !important;
    --spotim-border-color: #262c33 !important;
    --spotim-border-color-muted: #262c33 !important;
    --spotim-strong-border-color: #2d333b !important;
    --spotim-say-control-border-color: #2d333b !important;
    --spotim-message-separator-color: #262c33 !important;
    --spotim-input-separator-color: #2d333b !important;
    --spotim-star-color-empty: #2d333b !important;
    --spotim-progress-bar-background-color: #262c33 !important;
    --spotim-skeleton-background-color: #262c33 !important;
    --spotim-skeleton-foreground-color: #1c2128 !important;
    --spotim-content-loader-primary-color: #1c2128 !important;
    --spotim-content-loaders-secondary-color: #262c33 !important;
    --spotim-modal-backdrop-background-color: rgba(13, 17, 23, 0.7) !important;
    --spotim-safeframe-modal-backdrop-color: rgba(13, 17, 23, 0.7) !important;
  }
  /* OpenWeb's floating notifications bell is a SECOND shadow root (host:
     div[data-spot-im-shadow-host="floating-bell"]) whose 60px disc is a hardcoded
     `background-color:#fff` with no custom property behind it, so the vars above
     cannot reach it and it hung as a glaring white puck over every dark article.
     `filter: invert()` on the host DOES darken it -- but a filtered element becomes
     the containing block for its `position: fixed` descendants, and the bell then
     stops floating (it lands 4000px down the page). `opacity` creates no containing
     block, so knock the puck back with that instead: composited over the dark page it
     reads as a muted disc, its own glyph contrast is unchanged from the site's, and
     the button keeps floating and clicking. */
  div[data-spot-im-shadow-host="floating-bell"] {
    opacity: 0.35 !important;
  }

  /* ---- support.weather.com help centre ---------------------------------- */
  /* `domain("weather.com")` also matches the support subdomain, which runs a
     separate Salesforce Experience Cloud app (`slds-*` plus its own
     `cFeedbackCommunityV2*` components). Our text lifts reach it but none of
     its surfaces do, so its section headings land light-on-white and the
     article list is a 920x1363 white panel. Darken the app's own surfaces --
     its navy hero band, brand logos and the blue/white filter chips (blue =
     selected) are the site's own and stay. */
  .cFeedbackCommunityV2HomeContent,
  .cFeedbackCommunityV2Article,
  .brands,
  .articles-list,
  .article-card,
  .alert-detail-card,
  .sidebar,
  .search-form,
  .footer-v2,
  .slds-modal__content,
  .slds-modal__header,
  .slds-modal__footer {
    background-color: var(--wx-surface) !important;
  }
  /* its headline links are the Salesforce navy #0a3fa8, ~2:1 on that surface */
  .brand-title,
  .article-title {
    color: var(--wx-link) !important;
  }
  .brand-title:hover,
  .article-title:hover {
    color: var(--wx-link-hover) !important;
  }
  /* the footer's own #333 / #666 labels sit outside every text rule above */
  .footer-v2 .connect-label,
  .footer-v2 .footer-copyright {
    color: var(--wx-text-2) !important;
  }
  /* the current nav item is marked by a WHITE pill on the navy header bar, so
     it has to keep dark ink -- the anchor rule paints it our link blue at
     2.4:1 on its own fill. */
  .nav-pill-active {
    color: #204794 !important;
  }
  /* its SIBLINGS (Topics / Privacy / Alerts / What's New) sit directly on that same
     navy #204794 band, where the site paints them white at 72% alpha. The anchor rule
     repainted them --wx-link, which is 3.68:1 on the navy (an AA fail) and reads as a
     row of body links rather than a nav bar. The band is the site's own brand colour
     and is never darkened, so the label has to go back to white. `.link-style` is
     used ONLY by these four. The site gives them no hover state at all; brightening
     to full white keeps the nav's own hue instead of the blue our `a:hover` forces. */
  .link-style {
    color: rgba(255, 255, 255, 0.72) !important;
  }
  .link-style:hover {
    color: #ffffff !important;
  }
  /* the help centre's own accents are Salesforce-dark and drop below 3:1 once
     the surface behind them is: the AI-help heading, the muted brand badge,
     and the three platform badges (keyed on data-platform, since all three
     share one class). Keep each hue, lift the lightness. */
  .ai-help-title {
    color: var(--wx-text) !important;
  }
  /* the announcement strip's copy is an `oklch()` grey -- a colour syntax no
     rgb-parsing scan resolves -- at 2.38:1 on the page base. */
  .banner-text .text-gray {
    color: var(--wx-text-2) !important;
  }
  .brand-badge {
    color: var(--wx-text-muted) !important;
  }
  .platform-badge[data-platform="iOS"] {
    color: #6ea8f0 !important;
  }
  .platform-badge[data-platform="Android"] {
    color: #57bb7e !important;
  }
  .platform-badge[data-platform="Web"] {
    color: #b18ce0 !important;
  }
  /* Knowledge article bodies are authored rich text: every paragraph is a
     <span style="...color: #000000"> pasted from the editor, so the tag-level
     text rules never reach it and the article body renders black on black. */
  .article-body [style*="color: #000000"],
  .alert-detail-card [style*="color: #000000"] {
    color: var(--wx-text-2) !important;
  }
  /* the same editor also emits the article's SECTION HEADINGS as
     `<h2><strong><span style="color: #1a1a1a">`. That inline colour is a declaration on
     the span itself, so it beats the `h1..h6` lift that matches the <h2> two levels up,
     and every heading in the article rendered at 1.1:1 -- a wall of body copy with no
     visible structure. Attribute values are case-sensitive and the parser here rejects
     the ` i` flag, so both spellings are listed. */
  .article-body [style*="color: #1a1a1a"],
  .article-body [style*="color: #1A1A1A"] {
    color: var(--wx-text) !important;
  }
  /* the help centre's grey-500 metadata (#6b7280) reads 3.2:1 on the darkened card -- an
     AA fail on the article dateline, the view count, the filter-bar label and the
     sidebar's "Browse by Brand" caption. None of them carry a text-* utility, so the
     muted-token list above cannot reach them; pin the muted ink by their own classes. */
  .filter-label,
  .other-brands-label,
  .articles-count,
  .article-meta,
  .article-meta span,
  .meta-dot,
  .vote-item,
  .vote-item span,
  .helpful-label {
    color: var(--wx-text-muted) !important;
  }
  /* the breadcrumb's LAST crumb (the page you are on) is a plain <span> painted in an
     `oklch()` slate -- a notation an rgb-matching scan cannot pattern-match, and a colour
     no text rule of ours reaches, so the trail ended in an unreadable crumb after three
     blue links. Muted keeps it quieter than the links, as the site intends. */
  .breadcrumb-item.active,
  .breadcrumb-item.active span {
    color: var(--wx-text-muted) !important;
  }
  /* the Topics page's platform FILTER CHIPS are `.filter-btn`: white pill + #1a2a3a ink
     when unselected, a #204794 navy fill + white label when selected. On the site's white
     page the selected chip is the darkest thing in the row; on ours it is the LIGHTEST
     three that shout and the selected one sinks into the page, so the control reads
     backwards -- and the row is four pure-white blobs on a dark page besides. Neither
     scanner sees it: the chips are 34px tall (under the light-surface floor) and both
     states are achromatic-vs-brand exactly as the site paints them, so the chroma diff is
     empty. Sink the unselected chips to the elevated surface and give the selected one
     the theme accent, restoring the site's own inversion. The `.active` chip also ships
     `bg-blue-600`; matching the pair keeps us above the site's own two-class rule. */
  .filter-btn {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border-2) !important;
  }
  /* the chip's only hover feedback is its label and rim going navy, which the restated
     colour above would otherwise pin flat. */
  .filter-btn:hover {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  /* the selected chip has to come AFTER the hover rule: both are (0,2,0), so source
     order decides, and hovering the selected chip must not paint its label the same
     blue as its fill. */
  .filter-btn.active,
  .filter-btn.active.bg-blue-600 {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* the article's utility buttons are the same shape of miss one page over: the two
     thumb `.vote-btn`s and the `.action-btn` ("Print") are white pills, and the blanket
     `* { border-color }` had already turned their #e5e7eb hairline into a dark band
     across each white blob. */
  .vote-btn,
  .action-btn {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border-2) !important;
  }
  /* each of the two has its OWN hover move and the restatement above pins whichever
     property carries it: the vote pills take a navy label + rim and keep their fill,
     Print keeps its ink and gains a faint tint. Mirror them one for one. */
  .vote-btn:hover {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  .action-btn:hover {
    background-color: var(--wx-border) !important;
  }
  /* `.contact-btn` ("Email Us") is the OUTLINE half of the "Can't find what you're looking
     for?" pair -- white fill, navy label and navy rim, i.e. invisible-on-white by design.
     Filled in on our base it is a solid white slab beside the navy `.ai-btn`. Give it the
     outline treatment the site intends: no fill, accent label and rim. */
  .contact-btn {
    background-color: transparent !important;
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  /* its hover is the outline-to-filled flip, which the transparent fill above pins. */
  .contact-btn:hover {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* the Cookie Notice modal (the help centre's own, shown on a first visit and the only
     thing on screen when it is) footers two bare `slds-button_neutral` secondary buttons:
     white fill, navy label, navy-on-hover. On the site's white modal that is an outline
     pair beside the filled "Ok"; on the darkened modal they are two lit slabs and the
     brand CTA beside them stops being the loudest thing. Give them the same outline
     treatment `.contact-btn` gets. Scoped to the modal so the two buttons that already
     carry the class with a fill of their own (.ai-btn, .contact-btn) keep it. */
  .slds-modal .slds-button_neutral {
    background-color: transparent !important;
    color: var(--wx-link) !important;
    border-color: var(--wx-border-2) !important;
  }
  .slds-modal .slds-button_neutral:hover {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* the help-centre hero's Search button is white ON a white search form -- i.e. no plate
     at all natively, just a navy label and magnifier inside the pill. Darkening the form
     leaves the button as a bright pill the site never draws. */
  .search-form button {
    background-color: transparent !important;
    color: var(--wx-link) !important;
  }
  /* every in-app navigation in the Experience Cloud app (a nav pill, a topic row,
     an article link) mounts a `siteforceLoadingBalls` spinner whose plate is
     rgba(255, 255, 255, .8) -- a bright rectangle over the dark page for as long
     as the route takes. It exists in the DOM at display:none from first paint, so
     only a forced reveal of hidden subtrees finds it. Its dots are mid-grey and
     read on a dark plate. */
  .siteforceLoadingBalls {
    background-color: rgba(13, 17, 23, 0.85) !important;
  }

  /* the article header's product pill (`.brand-badge-outline`, "Storm Radar") keeps the
     Salesforce navy #204794 as its LABEL -- 1.9:1 on the dark card. */
  .brand-badge-outline {
    color: var(--wx-link) !important;
    border-color: var(--wx-border-2) !important;
  }

  /* ====================================================================== */
  /* Keep weather imagery / data viz untouched.                             */
  /* radar/satellite (DynamicMap + Mapbox tiles), condition icons, photos   */
  /* must render their real pixels -- never paint a background onto these.  */
  /* ====================================================================== */
  img,
  picture,
  video,
  canvas,
  [data-testid="DynamicMap"],
  [data-testid="DynamicMap"] *,
  .mapboxgl-map,
  .mapboxgl-canvas,
  [class*="mapbox"] {
    background-color: transparent !important;
  }
  [data-testid="DynamicMap"] *,
  .mapboxgl-map * {
    border-color: transparent !important;
  }
  /* ...but the map's own UI is NOT basemap: the blanket transparent rules above
     erased the two things drawn on top of it.
     - LocationPin is a `bg-[#1944DE] border-2 border-white` disc marking YOUR
       location -- it went fully invisible (transparent fill + dark ring), so
       the Today-page map showed no "you are here" marker at all.
     - DynamicMapTimeStamp is the "Now" chip, natively an rgba(37,36,34,.8) pill
       with white text; stripped of its fill it left light-blue link text
       floating on the bright map (~1.9:1).
     Both carry a data-testid, so restore them at (0,2,0) -- above the (0,1,0)
     neutralizers -- without touching a single map tile. */
  [data-testid="DynamicMap"] [data-testid="LocationPin"] {
    background-color: #1944de !important;
    border-color: #ffffff !important;
  }
  [data-testid="DynamicMap"] [data-testid="DynamicMapTimeStamp"] {
    background-color: rgba(13, 17, 23, 0.85) !important;
  }

  /* ====================================================================== */
  /* SVG data-viz chrome a DOM-background audit can't see.                  */
  /* These are weather.com's own SVG charts/gauges (NOT raster maps). Their */
  /* white track / grid / plot chrome is darkened while the COLORED data    */
  /* arcs / bars / series are preserved verbatim.                           */
  /* ====================================================================== */

  /* (0) the Today's Outlook "Precipitation Intensity Chart" is a <canvas>, so no
     selector reaches its pixels: each of the ~30 hour columns is drawn as a full-height
     #eeeeee TRACK with the actual precipitation painted as a coloured tip at its base.
     On the site's white card those tracks are invisible; on our dark card the strip
     rendered as a wall of glaring near-white bars with two small green tips. A canvas
     is unreachable by fill/background rules, but it IS filterable: invert + a 180deg
     hue rotation maps the #eeeeee track to a near-black one and the #676767 axis to a
     legible grey, while returning every saturated data colour to (very near) itself --
     the precip green stays green and the heavier blues stay blue. The chart carries a
     stable `aria-label`, so nothing else on the page is filtered. */
  [aria-label="Precipitation Intensity Chart"] canvas {
    filter: invert(1) hue-rotate(180deg);
  }
  /* the Cold & Flu "CDC Flu Report" bar chart is a <canvas> too (FluCDCReportModule):
     gridlines #ececec, axis labels #676767, the "Wk of" caption in the near-black ink,
     the case bars #3a61cc -- all pixels. The same chain maps the gridlines to #121212
     (as faint on the card as #ececec is on white), the labels to a legible grey, the
     caption to light, and the bars to a lighter blue (#789fff) that keeps their hue. */
  [data-testid="FluCDCReportModule"] canvas {
    filter: invert(1) hue-rotate(180deg);
  }

  /* (1) the semicircle wind/pressure gauge: track arc is a light #E7ECF1
     stroke. Darken the track; the colored value arc keeps its own stroke. */
  [data-testid="SemiCircleGauge"] path[stroke="#E7ECF1"],
  [data-testid="SemiCircleGauge"] path[stroke="#e7ecf1"] {
    stroke: var(--wx-border-2) !important;
  }

  /* (2) donut chart (AQI / health): the light track ring is the first circle,
     class stroke-[#E7ECF1] (Tailwind arbitrary stroke); the colored value arc
     is a 2nd circle with an inline saturated stroke (preserved). Darken only
     the track. */
  [data-testid="DonutChart"] circle[stroke="#E7ECF1"],
  [data-testid="DonutChart"] circle[class*="stroke-[#E7ECF1]"],
  [data-testid="DonutChart"] circle[class*="stroke-[#e7ecf1]"],
  /* weather.com now paints the donut TRACK ring's light #E7ECF1 stroke via a
     CSS-module class (DonutChart--track--<hash>) with NO stroke attribute, so the
     attribute selectors above no longer match and the track rendered a bright
     white ring -- glaring on low-percentage donuts (the Cold & Flu "Type B 1%"
     donut showed an almost-full white circle). Match the track by its stable
     module-class prefix; the value arc (DonutChart--indicator) keeps its data
     color (blue / orange / green). */
  [data-testid="DonutChart"] circle[class*="DonutChart--track"],
  circle[class*="DonutChart--track"],
  .stroke-\[\#E7ECF1\],
  .stroke-\[\#e7ecf1\] {
    stroke: var(--wx-border-2) !important;
  }
  [data-testid="DonutChart"] circle[fill="#fff"],
  [data-testid="DonutChart"] circle[fill="#ffffff"],
  [data-testid="DonutChart"] circle[fill="white"] {
    fill: var(--wx-surface) !important;
  }
  /* (2b) the gauge CENTER VALUE text (the AQI "26", UV index, pollutant
     numbers, etc.) is an SVG <text> whose color comes from a Tailwind
     `fill-text-*` utility that resolves to a NEAR-BLACK token -- so the number
     goes dark-on-dark and vanishes on the dark gauge. (A DOM-bg audit can't see
     SVG text fill.) Lift it to primary light. The colored arc keeps its own
     stroke; only the value/label text is recolored. */
  [data-testid="DonutChart"] text,
  [data-testid="DonutChart"] tspan,
  [data-testid="SemiCircleGauge"] text,
  [data-testid="SemiCircleGauge"] tspan,
  svg text[class*="fill-text-"],
  svg tspan[class*="fill-text-"] {
    fill: var(--wx-text) !important;
  }

  /* (2c) the WIND COMPASS is a bare <svg> with no testid: a dashed #d1d5db dial
     ring, a #6b7280 "N" label, and the direction needle drawn as three
     near-black #1f2937 shapes (line shaft, hub circle, arrowhead polygon).
     Nothing about it is an HTML box, so every background audit passed while the
     needle -- the entire point of the widget -- rendered #1f2937 on our #1c2128
     card and disappeared, leaving only a glaring white dial. Flip the needle to
     light, mute the "N", and drop the dial ring to the component border so it
     stays as subtle against dark as #d1d5db was against white. */
  svg line[stroke="#1f2937"] {
    stroke: var(--wx-text) !important;
  }
  svg circle[fill="#1f2937"],
  svg polygon[fill="#1f2937"] {
    fill: var(--wx-text) !important;
  }
  svg text[fill="#6b7280"] {
    fill: var(--wx-text-muted) !important;
  }
  /* (2d) the Sunrise-Sunset and Moonrise-Moonset arcs draw the sun/moon PATH as
     a #111827 stroke with #111827 end dots (sunrise + sunset markers) over a
     #f3f4f6 ground rect, with #d1d5db dotted time guides. The arc and both dots
     went dark-on-dark: the widget showed two labels and an empty sky. */
  svg path[stroke="#111827"] {
    stroke: var(--wx-text) !important;
  }
  svg circle[fill="#111827"] {
    fill: var(--wx-text) !important;
  }
  svg circle[stroke="#d1d5db"],
  svg line[stroke="#d1d5db"] {
    stroke: var(--wx-border-2) !important;
  }

  /* (3) bar/line chart plot backgrounds shipped as a white <rect> behind the
     plot. Darken the chart's own white backdrop rects; colored data bars keep
     their fill. Raster radar/satellite maps are <canvas>/Mapbox tiles (no
     <svg><rect>), so this never touches map pixels. */
  svg > rect[fill="white"],
  svg > rect[fill="#fff"],
  svg > rect[fill="#ffffff"],
  svg rect[fill="#F2F2F2"],
  svg rect[fill="#f2f2f2"],
  svg rect[fill="#f3f4f6"],
  svg rect[fill="#F3F4F6"],
  svg rect[fill="#E7ECF1"],
  svg rect[fill="#e7ecf1"] {
    fill: var(--wx-surface-2) !important;
  }
  /* gauge tick marks / faint gridline strokes shipped as light #E7ECF1 */
  [data-testid="SemiCircleGauge"] line[stroke="#E7ECF1"],
  [data-testid="SemiCircleGauge"] line[stroke="#e7ecf1"],
  svg path[stroke="#E7ECF1"],
  svg path[stroke="#e7ecf1"] {
    stroke: var(--wx-border-2) !important;
  }
  /* near-black chart axis text / gridlines -> readable muted light */
  svg text[fill="#252422"],
  svg text[fill="rgb(37, 36, 34)"],
  svg line[stroke="#E7ECF1"],
  svg line[stroke="#e7ecf1"],
  svg line[stroke="#EFEFEF"] {
    fill: var(--wx-text-muted) !important;
    stroke: var(--wx-border) !important;
  }
}
